/* A116 staged author data. Promote to author_depth_zz116.js only after full audit. */
(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('retrospect','Retrospect comes from Latin retrospectare, “look back,” from retro (“back”) and spectare (“look at”).',[C('retrospect.s1','事后看来','In retrospect, the team should have tested the backup generator before the storm arrived.','事后看来，团队本该在暴风雨来临前测试备用发电机。','In retrospect / the team should have tested / the backup generator earlier.','固定短语 in retrospect 常用于回顾后作出的判断。','说话者是在事情发生后回看当时的决定。'),C('retrospect.s2','回想；追溯','She likes to retrospect on her first year abroad and compare it with life now.','她喜欢回想自己在国外的第一年，并把那时与现在的生活作比较。','She likes to retrospect on her first year / and compare it / with life now.','retrospect.s2 作动词，指回想过去的事件。','她回顾过去并与现在比较。')],M('In retrospect, the team knew the storm would arrive and tested the generator before it happened.','In retrospect, the team realized afterward that it should have tested the generator earlier.','in retrospect 表示事后回看；句中却把判断放在事前。','meaning'),[q('What did the team realize in retrospect?','it should have tested the backup generator earlier','it had already tested every storm cloud','it should replace the museum reporter','事后看来，团队意识到本该更早测试发电机。',1,'context'),q('Which expression best completes “___, I would choose a quieter route”?','In retrospect','At noon tomorrow','On the generator','回顾过去并重新评价决定时可用 in retrospect。',1,'meaning'),q('What does retrospect mean as a verb in the second example?','look back at earlier events','repair a generator','predict an event before it occurs','retrospect 作动词指回想早先的事。',2,'meaning'),q('Which Latin element in retrospectare means “back”?','retro','spectare','generator','retro 表示“向后、回到过去”。',1,'word-formation')]);
P('retrospection','Retrospection is formed from retrospect and -ion; its history goes back to Latin retrospectio, the act of looking back.',C('retrospection.s1','回顾；反思','His retrospection on the failed expedition identified two decisions that the crew would change next time.','他回顾失败的探险，指出船员下次会改变的两个决定。','His retrospection on the expedition / identified two decisions / to change next time.','retrospection 是对过去经历的认真回顾。','回顾使他找出下次需要改变的决定。'),M('Her retrospection on the expedition described plans for a trip that had not yet taken place.','Her retrospection on the expedition examined decisions made during the trip that had already ended.','尚未发生的行程不能成为回顾对象。','meaning'),[q('What did his retrospection identify?','two decisions to change next time','two routes that were never considered','two new boats for the next storm','他回顾后找出下次要改变的两个决定。',1,'context'),q('When does retrospection happen?','while looking back at past events','before any event has happened','only while predicting tomorrow’s weather','retrospection 指回顾已发生的事情。',1,'meaning'),q('Which activity is retrospection?','reviewing a completed project to learn what went wrong','planning an expedition before it begins','testing a generator during a storm','复盘已完成的项目属于 retrospection。',1,'context'),q('Which ending makes retrospect into the noun retrospection?','-ion','-ly','-er','retrospect 加 -ion 形成表示行为的名词 retrospection。',1,'word-formation')]);
P('retrospective','Retrospective is from Latin retrospectare (“look back”) with the adjective-forming -ive; as a noun it can also mean an exhibition reviewing an artist’s work.',[C('retrospective.s1','追溯的；回顾的','The retrospective review compared the policy’s original goals with the results measured ten years later.','这份回顾性评估把政策最初目标与十年后测得的结果作了比较。','The retrospective review compared / the policy’s original goals / with later results.','retrospective.s1 作形容词，表示回顾过去的。','评估把初始目标与后来的结果比较。'),C('retrospective.s2','回顾展','The museum opened a retrospective of the painter’s work, bringing together canvases from every decade of her career.','博物馆举办了这位画家的回顾展，汇集她职业生涯每个年代的画作。','The museum opened a retrospective / bringing together canvases / from every decade.','retrospective.s2 作名词，指回顾艺术家创作历程的展览。','展览汇集了画家各时期作品。')],M('The museum’s retrospective displayed only paintings created next year and excluded the artist’s earlier work.','The museum’s retrospective displayed works from different periods of the artist’s career.','回顾展呈现已往创作历程，不会只展出尚未创作的未来作品。','meaning'),[q('What did the policy review compare?','the original goals and results measured later','two paintings that have not yet been made','the artist’s studio and a storm generator','回顾性评估比较政策初衷与后来结果。',1,'context'),q('What did the museum retrospective bring together?','canvases from every decade of the painter’s career','only paintings created next year','reports from the policy office','回顾展汇集画家不同时期的画作。',2,'context'),q('In “a retrospective review,” what does retrospective mean?','looking back at the past','planning something for the future','showing only one current event','这里 retrospective 表示回顾过去的。',1,'meaning'),q('As a noun, what is a retrospective at a museum?','an exhibition reviewing an artist’s body of work','a report about a future storm','a device used to test a generator','名词 retrospective 可指艺术家作品回顾展。',2,'meaning')]);
P('return','Return came through Old French returner, “come back,” from re- (“back”) and tourner (“turn”); it can mean come back, give something back, or a return/profit/form.',[C('return.s1','返回；回来','The hikers will return to the village before sunset if the mountain pass remains clear.','如果山口仍然畅通，徒步者会在日落前返回村庄。','The hikers will return to the village / before sunset / if the pass stays clear.','return.s1 指回到原来的地方。','徒步者回到出发的村庄。'),C('return.s2','归还；退回','Please return the borrowed microscope to the science room after your lesson.','课程结束后，请把借来的显微镜归还科学教室。','Please return the borrowed microscope / to the science room / after class.','return.s2 指把借来的东西交还。','显微镜被送回原处。'),C('return.s3','回报；收益；申报表','The investment produced a modest return, and the accountant filed the company’s annual tax return.','这笔投资带来适度收益，会计也提交了公司的年度纳税申报表。','The investment produced a modest return / and the accountant filed / an annual tax return.','return.s3 可指收益或正式申报表。','同句中 return 分别指收益和税表。')],M('After the lesson, the student returned the borrowed microscope by keeping it at home permanently.','After the lesson, the student returned the microscope by taking it back to the science room.','归还要求把物品交还原主或原处，永久留下与之相反。','meaning'),[q('Where will the hikers go before sunset?','back to the village','to a new mountain pass','to the science room','徒步者会在日落前回到村庄。',1,'context'),q('What should students do with the borrowed microscope?','give it back to the science room','keep it at home permanently','file it as a tax return','学生应把借来的显微镜归还教室。',2,'context'),q('What did the investment produce?','a modest profit or return','a borrowed microscope','a mountain pass','投资带来了一定收益。',3,'context'),q('In “file the annual tax return,” what is a return?','an official tax form','a person coming back to a place','a borrowed object being given back','这里 return 指正式的纳税申报表。',3,'meaning')]);
P('reunion','Reunion combines re- (“again”) and union; it names a meeting of people who have been apart, or an organized gathering of a former group.',[C('reunion.s1','团聚；重聚','After five years overseas, Lina’s reunion with her siblings brought the whole family together again.','在海外生活五年后，莉娜与兄弟姐妹重聚，全家再次团圆。','Lina’s reunion with her siblings / brought the family together / after five years apart.','reunion.s1 指分开一段时间的人再次相聚。','兄弟姐妹多年分离后团聚。'),C('reunion.s2','同学会；联谊会','The university organized a reunion for the class that graduated twenty years earlier.','大学为二十年前毕业的那届学生组织了一场同学会。','The university organized a reunion / for the graduating class / from twenty years ago.','reunion.s2 指为旧同学或旧成员安排的聚会。','毕业生参加组织好的同学会。')],M('The siblings held a reunion while remaining separated in different countries and refusing to meet.','The siblings held a reunion by meeting again after years apart.','reunion 指分开的人再次聚在一起，不见面就不构成团聚。','meaning'),[q('How long had Lina lived overseas before the family reunion?','five years','twenty years','one month','莉娜在海外生活五年后与家人重聚。',1,'context'),q('Who was invited to the university reunion?','the class that graduated twenty years earlier','a group that has not yet enrolled','the hikers returning before sunset','大学为二十年前毕业的同学组织聚会。',2,'context'),q('What is a reunion?','a meeting again after people have been apart','a first meeting between strangers','a form filed with a tax office','reunion 指分开的人再次相见。',1,'meaning'),q('What does re- mean in reunion?','again','before','against','re- 表示“再次”，union 是结合或团聚。',1,'word-formation')]);
P('reunite','Reunite combines re- and unite; it means come together again or bring separated people or things together again.',[C('reunite.s1','重聚；团聚','The old band will reunite for one concert after its members have spent a decade pursuing separate careers.','乐队成员各自发展十年后，将为一场音乐会重新聚首。','The old band will reunite / for one concert / after a decade apart.','reunite.s1 作不及物用法，表示分开的成员再次相聚。','乐队成员多年分开后再次聚首。'),C('reunite.s2','使重聚；重新结合','A volunteer helped reunite the lost child with her parents at the crowded station.','一名志愿者在拥挤的车站帮助走失的孩子与父母团聚。','A volunteer helped reunite the child / with her parents / at the station.','reunite.s2 作及物用法，表示使分开的人或部分重新结合。','志愿者帮助孩子与父母重聚。')],M('The volunteer reunited the child with her parents by sending each of them to a different city.','The volunteer reunited the child with her parents by bringing them together at the station.','把孩子和父母送往不同城市不能使他们团聚。','meaning'),[q('Why will the old band reunite?','to perform one concert','to file a tax return','to visit a mountain pass','乐队成员将为一场音乐会重新聚首。',1,'context'),q('Who helped reunite the child with her parents?','a volunteer','the old band’s accountant','a museum curator','志愿者帮助走失孩子与父母团聚。',2,'context'),q('In “the band will reunite,” is reunite transitive or intransitive?','intransitive: the members come together again','transitive: it brings a lost child to parents','a noun naming a school gathering','句中乐队成员自己重新聚在一起，reunite 不带宾语。',1,'meaning'),q('In “reunite the child with her parents,” what does reunite mean?','bring separated people together again','return borrowed equipment','review an artist’s work','这里 reunite 是使分离的人再次团聚。',2,'meaning')]);
P('reuse','Reuse combines re- and use; it means use something again, often instead of discarding it after one use.',C('reuse.s1','再次使用；重复利用','The café washes its sturdy glass jars so it can reuse them for take-away sauces.','咖啡馆清洗结实的玻璃罐，以便再次用来装外带酱料。','The café washes glass jars / so it can reuse them / for take-away sauces.','reuse 指把已经用过的东西再次使用。','玻璃罐清洗后继续装酱料。'),M('The café reused its jars by smashing them after one use and sending the pieces to landfill.','The café reused its jars by washing them and filling them again.','打碎并丢弃容器不是再次使用。','meaning'),[q('What does the café reuse?','sturdy glass jars','single-use paper receipts','a returned mountain pass','咖啡馆清洗玻璃罐后再次使用。',1,'context'),q('What happens before the jars are reused?','they are washed','they are smashed','they are sent to landfill','玻璃罐在再次使用前会清洗。',1,'context'),q('What does reuse mean?','use something again','return something to its original owner only','change the structure to improve it','reuse 指再次使用某物。',1,'meaning'),q('Which prefix in reuse means “again”?','re-','un-','pre-','reuse 中的 re- 表示“再次”。',1,'word-formation')]);
P('revaluation','Revaluation combines re- and valuation; it means assessing value again, and in economics it can mean an official increase in a currency’s value.',[C('revaluation.s1','重新估价；再评价','The council ordered a revaluation of the historic houses after a new survey revealed major structural differences.','新调查发现房屋结构差异很大后，市议会要求重新评估这些历史建筑。','The council ordered a revaluation / after the new survey / revealed structural differences.','revaluation.s1 指再次评估某物的价值。','新调查促使市议会重新估价。'),C('revaluation.s1','货币升值','The government announced a revaluation of the currency, raising its official exchange value against the dollar.','政府宣布本币升值，提高其对美元的官方汇率。','The government announced a currency revaluation / raising its official value / against the dollar.','revaluation.s2 在经济领域可指官方提高货币价值。','本币官方汇率上调。')],M('The council called its decision a revaluation even though it refused to assess the houses again and simply copied last year’s figures.','The council called its decision a revaluation because the new survey led it to assess the houses’ worth again.','没有重新评估价值，只照抄旧数据，不构成 revaluation。','meaning'),[q('Why did the council order a revaluation of the houses?','a new survey found structural differences','the currency exchange value rose','the café reused its glass jars','新调查揭示房屋结构差异，因此市议会要求重新评估。',1,'context'),q('What changed in the government’s currency revaluation?','the official exchange value rose','the currency was discarded','the council assessed historic houses','政府提高了本币的官方汇率。',1,'context'),q('What is a revaluation in its general sense?','an assessment of value made again','a first meeting after a separation','the act of using a jar again','revaluation 的一般意思是再次评估价值。',1,'meaning'),q('Which two parts form revaluation?','re- and valuation','re- and union','retro- and spectate','revaluation 由 re- 与 valuation 组合，表示重新估价。',1,'word-formation')]);
P('revamp','Revamp appeared in the eighteenth century with the sense “patch or renovate”; its exact formation is uncertain, and today it means improve something by changing its design or structure.',C('revamp.s1','翻新；改造','The library will revamp its entrance by widening the doors and adding a quiet study area.','图书馆将拓宽入口并增设安静学习区，以改造入口空间。','The library will revamp its entrance / by widening the doors / and adding a study area.','revamp 指通过改变设计或结构来改善某物。','图书馆将调整入口布局。'),M('The library revamped its entrance by preserving every feature unchanged and making no improvement to the space.','The library revamped its entrance by changing the layout and adding a study area.','保持所有部分完全不变且不作改善，与改造含义相反。','meaning'),[q('What changes are part of the library’s revamp?','wider doors and a quiet study area','a higher currency exchange value','a reunion concert for an old band','图书馆将拓宽入口并增加学习区。',1,'context'),q('What does revamp mean?','improve something by changing its design or structure','use an object again without changing it','look back at a completed event','revamp 指通过改造来改善某物。',1,'meaning'),q('Which project is a revamp?','redesigning a clinic lobby to improve access','keeping a lobby exactly as it is','reviewing an artist’s past paintings','重新设计诊所大厅以改善通行属于 revamp。',1,'context'),q('What is known about revamp’s exact formation?','it is uncertain','it definitely comes from Latin revaluation','it is formed from reunion plus -ment','revamp 的确切构词来源并不确定，因此不应编造词根。',1,'word-formation')]);
P('reveal','Reveal comes through Old French reveler from Latin revelare, “unveil,” from re- and velare (“cover with a veil”); it can make hidden information known or allow something concealed to be seen.',[C('reveal.s1','透露；揭示','The audit will reveal whether the contractor charged the city for work that was never completed.','审计将揭示承包商是否向市政府收取了未完成工程的费用。','The audit will reveal / whether the contractor charged / for unfinished work.','reveal.s1 指使秘密或未知信息为人所知。','审计揭示账目是否存在问题。'),C('reveal.s2','显露；展示','When the curtains opened, the stage lights revealed a narrow bridge set above a dark pool.','帷幕拉开时，舞台灯光照出一座架在黑色水池上方的窄桥布景。','The stage lights revealed a narrow bridge / above the dark pool / as the curtains opened.','reveal.s2 指让隐藏或遮挡的事物显现出来。','灯光使布景显露出来。')],M('The audit revealed the contractor’s billing by hiding every record and ensuring that nobody could learn what had happened.','The audit revealed the contractor’s billing by making the hidden payment records available for review.','把记录藏起来不会揭示账目。','meaning'),[q('What will the audit reveal?','whether the contractor billed for unfinished work','whether the old band will hold a reunion','whether the café can reuse jars','审计将揭示是否对未完成工程收费。',1,'context'),q('What did the stage lights reveal?','a narrow bridge set above a pool','a hidden tax return in the library','a new exchange rate','灯光照出了水池上方的窄桥布景。',2,'context'),q('What does reveal mean in “reveal a secret”?','make hidden information known','make something disappear','use something for the first time','reveal a secret 指揭示秘密。',1,'meaning'),q('What does Latin velare mean in the history of reveal?','cover with a veil','look back','come together','velare 有“用面纱遮盖”的意思，与 reveal 的“揭开”相对。',1,'word-formation')]);
P('revealing','Revealing is the present participle of reveal; as an adjective it can disclose a hidden fact or describe clothing that shows much of the wearer’s body.',[C('revealing.s1','揭示真相的；说明问题的','The revealing email showed that managers had known about the safety risk months before the public announcement.','这封揭示真相的邮件表明，管理人员在公开公告前数月就已知道安全风险。','The revealing email showed / that managers knew / about the risk months earlier.','revealing.s1 指提供线索、揭示隐藏事实的。','邮件透露了管理层早已知情。'),C('revealing.s2','暴露身体的','The performer changed into a less revealing costume before the family matinee.','这位表演者在家庭场次演出前换上了一套不那么暴露的服装。','The performer changed into a less revealing costume / before the family matinee.','revealing.s2 描写露出较多身体部位的衣着。','演出前更换了较不暴露的服装。')],M('The revealing email concealed every fact about the safety risk and offered no information about managers’ knowledge.','The revealing email exposed the fact that managers knew about the safety risk earlier.','完全没有透露任何事实的邮件不能称为揭示真相的。','meaning'),[q('What did the revealing email show?','managers knew about the risk months earlier','the costume showed more skin','the library entrance had wider doors','邮件揭示管理人员早已知晓安全风险。',1,'context'),q('Why did the performer choose a less revealing costume?','for the family matinee','to announce a currency revaluation','to audit the contractor','表演者为家庭场次换上不那么暴露的服装。',2,'context'),q('Which meaning of revealing applies to the email?','disclosing a hidden fact','showing a lot of the wearer’s body','bringing separated people together','邮件中的 revealing 指揭露隐藏事实。',1,'meaning'),q('Which meaning applies to revealing clothing?','clothing that shows much of the wearer’s body','an email that proves managers knew something','a review of an artist’s career','revealing clothing 指比较暴露的衣服。',2,'meaning')]);
P('revealingly','Revealingly is formed from revealing and -ly; it means in a way that discloses a hidden motive, fact, or feeling.',C('revealingly.s1','透露实情地；说明问题地','When asked about the missing funds, the director revealingly changed the subject to next year’s budget.','被问及失踪款项时，主任意味深长地把话题转向明年的预算。','The director revealingly changed the subject / when asked / about the missing funds.','revealingly 修饰动作，表示其方式透露了隐藏事实或动机。','转移话题的反应透露了主任的回避态度。'),M('The director answered every question about the missing funds directly and transparently, revealingly hiding no motive or fact.','The director revealingly changed the subject when questioned about the missing funds.','直接透明地回答而不隐瞒，不符合 revealingly 所表达的意味深长地透露。','meaning'),[q('What topic did the director switch to?','next year’s budget','the performer’s costume','the artist’s retrospective','主任把话题转向明年的预算。',1,'context'),q('What does the director’s reaction revealingly suggest?','the subject change may expose avoidance or a motive','the director has already reunited the band','the missing funds were used to replant trees','意味深长地转移话题可能透露其回避或动机。',1,'meaning'),q('Which action is done revealingly?','a witness pauses conspicuously before denying a connection','a clerk silently files a form without any clue','a hiker returns to a village before sunset','证人否认前明显停顿，可能透露某些信息。',1,'context'),q('Which word is the base of revealingly?','revealing','reunion','revaluation','revealingly 由 revealing 加 -ly 构成。',1,'word-formation')]);
P('revegetate','Revegetate combines re- and vegetate, ultimately from Latin vegetare (“make grow”); it means establish vegetation again on bare or damaged ground.',C('revegetate.s1','恢复植被；重新绿化','After the mine closed, ecologists revegetated the bare slopes with native grasses and shrubs.','矿山关闭后，生态学家用本地草类和灌木恢复了裸露山坡的植被。','Ecologists revegetated the bare slopes / with native grasses / after the mine closed.','revegetate 指在裸露或受损土地上再次建立植被。','矿山关闭后山坡重新种上本地植物。'),M('The ecologists revegetated the slope by removing the remaining plants and leaving the ground bare.','The ecologists revegetated the slope by planting native grasses and shrubs on the bare ground.','清除植物并留下裸地与恢复植被相反。','meaning'),[q('What did ecologists plant on the mine slopes?','native grasses and shrubs','glass jars and microscope parts','the old band’s instruments','生态学家种植本地草类和灌木来恢复山坡植被。',1,'context'),q('What does revegetate mean?','establish vegetation again on land','remove every plant from land','review an artist’s past work','revegetate 指在土地上重新建立植被。',1,'meaning'),q('Which place most needs revegetation?','bare ground damaged by mining','a crowded reunion hall','a tax office with a new form','采矿后裸露的土地需要恢复植被。',1,'context'),q('What does vegetate contribute to revegetate?','the idea of growing or putting in vegetation','the idea of looking back','the idea of returning borrowed equipment','vegetate 与生长或植被有关，re- 表示再次。',1,'word-formation')]);
P('revel','Revel came through Old French reveler, used of lively, disorderly merrymaking; as a verb it means enjoy oneself noisily or take great pleasure in something.',[C('revel.s1','纵情欢乐；狂欢','The graduates reveled in the music and dancing at the outdoor celebration until midnight.','毕业生在户外庆典上尽情享受音乐和舞蹈，直到午夜。','The graduates reveled in the music / and dancing / until midnight.','revel.s1 指与他人热闹地尽情欢乐。','毕业生在庆典中欢庆。'),C('revel.s2','陶醉；沉浸','Maya revels in solving difficult puzzles, often spending hours on a single clue.','玛雅非常享受解难题，常常为一个线索花上数小时。','Maya revels in solving puzzles / often spending hours / on one clue.','revel.s2 指从某事中获得极大乐趣。','玛雅沉浸于解谜的乐趣。')],M('The graduates reveled at the celebration by leaving before it began and avoiding all music and company.','The graduates reveled at the celebration by enjoying the music and dancing with their classmates.','没有参加或享受庆典不符合 revel 的尽情欢乐义。','meaning'),[q('What did the graduates enjoy at the celebration?','music and dancing','an audit of missing funds','a quiet review of tax forms','毕业生在庆典上享受音乐和舞蹈。',1,'context'),q('What does Maya revel in?','solving difficult puzzles','replanting a mined slope','returning a borrowed microscope','玛雅非常享受解难题。',2,'context'),q('Which sense of revel appears in the sentence about Maya?','take great pleasure in an activity','celebrate noisily with a group','return something to its owner','Maya 的句子中 revel 指从解谜中获得乐趣。',1,'meaning'),q('Which scene best illustrates revel at a party?','guests dancing and celebrating together','guests leaving before the music starts','a clerk quietly filing a tax form','客人一起跳舞欢庆体现 revel 的狂欢义。',1,'context')]);
P('revelation','Revelation comes from Latin revelatio, from revelare (“unveil”); it means disclosing something hidden or a surprising important discovery.',[C('revelation.s1','揭露；透露','The revelation that the bridge inspection had been skipped prompted an immediate safety review.','桥梁检查曾被跳过这一消息披露后，相关部门立即开展安全复查。','The revelation that inspection was skipped / prompted / an immediate safety review.','revelation.s1 指揭示原本隐藏的信息这一行为或事实。','检查被跳过的事实被揭露。'),C('revelation.s2','令人惊讶的发现；启示','For the new gardener, learning that compost could improve the clay soil was a revelation.','对这位新园丁来说，得知堆肥能改善黏土是个令人惊喜的发现。','Learning that compost helped clay soil / was a revelation / for the new gardener.','revelation.s2 指令人惊讶且重要的新发现。','园丁发现堆肥能改善土壤。')],M('The revelation about the bridge inspection was kept completely secret, and no one learned that the check had been skipped.','The revelation about the bridge inspection made the skipped safety check known.','从未公开且无人得知的信息没有被揭露。','meaning'),[q('What prompted an immediate safety review?','the disclosure that an inspection had been skipped','the discovery that compost helps clay soil','the band’s reunion concert','检查被跳过的消息披露后启动了安全复查。',1,'context'),q('What was a revelation for the new gardener?','compost could improve clay soil','the bridge had not been inspected','the band would reunite','堆肥能改善黏土是园丁的新发现。',2,'context'),q('What is a revelation in the first sentence?','the making-known of hidden information','a routine return to a village','a party for former classmates','第一句中的 revelation 指隐藏事实被揭露。',1,'meaning'),q('What does Latin revelare mean?','unveil','revalue','reunite','revelation 来自 revelare，意为“揭开面纱、揭示”。',1,'word-formation')]);
P('revenge','Revenge came through Old French revenchier, “take revenge”; it names harmful retaliation or can mean punish someone for a wrong.',[C('revenge.s1','报复；报仇','The novel’s hero rejected revenge and chose to seek justice through a public trial.','小说主人公拒绝报复，选择通过公开审判寻求正义。','The hero rejected revenge / and chose to seek justice / through a public trial.','revenge.s1 作名词，指为了惩罚伤害自己的人而进行的有害报复。','主人公放弃报复，转而寻求审判。'),C('revenge.s2','为……报仇','In the final chapter, the detective vows to revenge the victim by exposing the corrupt official.','在最后一章，侦探发誓要揭露腐败官员，为受害者报仇。','The detective vows to revenge the victim / by exposing / the corrupt official.','revenge.s2 作动词，后接受害者，表示为其报仇。','侦探为受害者伸张正义。')],M('The hero took revenge by forgiving the attacker, refusing any retaliation, and never trying to punish the harm.','The hero took revenge by retaliating against the attacker for the harm done.','原句描述的是宽恕且拒绝报复，并非 revenge。','meaning'),[q('What did the novel’s hero choose instead of revenge?','seeking justice through a public trial','punishing an innocent bystander','reuniting with the corrupt official','主人公选择通过公开审判寻求正义，而非报复。',1,'context'),q('How does the detective plan to revenge the victim?','by exposing the corrupt official','by hiding the bridge inspection','by returning to the village','侦探打算揭露腐败官员，为受害者报仇。',2,'context'),q('In the first sentence, is revenge a noun or a verb?','noun naming retaliation','verb meaning to return an object','adjective describing a review','the hero rejected revenge 中 revenge 是名词。',1,'meaning'),q('In “revenge the victim,” what does revenge mean?','punish someone for a wrong done to another','assess a value again','bring people together','revenge the victim 指为受害者惩罚加害者或伸张正义。',1,'meaning')]);
P('revenue','Revenue comes from Old French revenue, the feminine past participle of revenir (“come back”); it means money received by a government or business.',[C('revenue.s1','政府税收；岁入','The city’s tax revenue funded repairs to public schools and the replacement of aging water pipes.','市政府的税收收入用于维修公立学校并更换老旧水管。','The city’s tax revenue funded / school repairs / and replacement water pipes.','revenue.s1 指政府收到的税款或岁入。','税收收入支持公共设施维修。'),C('revenue.s2','公司营业收入','Online subscriptions now account for half of the publisher’s annual revenue.','网络订阅如今占这家出版商年营业收入的一半。','Online subscriptions account for half / of the publisher’s annual revenue.','revenue.s2 指企业从销售或服务中获得的钱。','订阅是出版商的重要收入来源。')],M('The publisher’s revenue fell even as no money entered the business from subscriptions, sales, or any other source.','The publisher’s revenue rose as subscription payments brought money into the business.','没有任何资金流入时，不应说企业收入增加。','meaning'),[q('What did the city’s tax revenue fund?','school repairs and water-pipe replacement','the novelist’s revenge plot','the reunion of a university class','城市税收用于学校维修和更换水管。',1,'context'),q('What provides half of the publisher’s annual revenue?','online subscriptions','taxes collected by the city','fees from a bridge inspection','出版商一半的年收入来自网络订阅。',2,'context'),q('What does revenue mean for a business?','money received from sales or services','money it has spent on repairs','a tax form filed each year','企业 revenue 指销售或服务带来的收入。',2,'meaning'),q('Which French verb is connected with revenue’s history?','revenir, “come back”','reveler, “celebrate”','replacer, “put in place”','revenue 源自表示“回来”的 revenir。',1,'word-formation')]);
P('reverberate','Reverberate comes from Latin reverberare, “beat back”; it means echo repeatedly or continue to have a strong effect.',[C('reverberate.s1','回响；回荡','The drumbeat reverberated through the stone tunnel long after the musicians had stopped playing.','乐手停止演奏很久后，鼓声仍在石隧道中回荡。','The drumbeat reverberated / through the stone tunnel / after the playing stopped.','reverberate.s1 指声音在空间中反复回响。','鼓声在隧道里持续回荡。'),C('reverberate.s2','产生持续影响','The court’s ruling will reverberate across the industry because it changes how contractors share liability.','法院的裁决将对整个行业产生持续影响，因为它改变了承包商分担责任的方式。','The ruling will reverberate across the industry / because it changes / shared liability.','reverberate.s2 指某事件产生广泛、持续的影响。','裁决将影响整个行业。')],M('The drumbeat reverberated in the tunnel by stopping instantly with no echo or lingering sound.','The drumbeat reverberated in the tunnel by echoing after the musicians had stopped.','声音立刻停止且没有回声，不符合 reverberate 的回荡义。','meaning'),[q('Where did the drumbeat reverberate?','through the stone tunnel','across the publishing industry','inside a tax form','鼓声在石隧道中回荡。',1,'context'),q('Why will the court ruling reverberate across the industry?','it changes how contractors share liability','it increases tax revenue for the city','it reunites a band for one concert','裁决改变承包商责任分担方式，因此会持续影响行业。',2,'context'),q('Which meaning of reverberate applies to the drumbeat?','echo repeatedly in a space','produce tax income','make hidden information known','鼓声的 reverberate 指在空间中回响。',1,'meaning'),q('Which use is figurative rather than about sound?','The new safety rule reverberated through the industry.','The drum reverberated inside the tunnel.','The bell echoed once in the hall.','安全规定 reverberated through the industry 是“产生持续影响”的比喻用法。',2,'meaning')]);
P('reverberation','Reverberation comes from Latin reverberatio, from reverberare (“beat back”); it is an echo or lingering sound after the original sound stops.',C('reverberation.s1','回响；余音','The hall’s long reverberation made the final piano chord linger after the performer lifted her hands.','大厅的长回响使演奏者抬手后最后一个钢琴和弦仍久久不散。','The hall’s long reverberation / made the final chord linger / after the performer stopped.','reverberation 指原声停止后仍持续、渐弱的回响。','琴声在大厅里余音不散。'),M('The hall had a long reverberation because every sound vanished immediately and no echo remained.','The hall had a long reverberation because sounds echoed and lingered after they stopped.','声音立即消失且没有回声，不是长时间的 reverberation。','meaning'),[q('What lingered after the performer lifted her hands?','the final piano chord','the city’s tax revenue','the band’s reunion invitation','演奏者抬手后，最后的琴声仍在大厅中回响。',1,'context'),q('What is reverberation?','an echo or lingering sound','a government’s tax income','a meeting of former classmates','reverberation 指回响或余音。',1,'meaning'),q('Which room would have noticeable reverberation?','a stone hall where a clap echoes for seconds','a padded booth where sound is absorbed','an open field with no walls','拍手声会回荡数秒的石厅有明显 reverberation。',1,'context'),q('Which verb underlies reverberation?','reverberate','reunite','reveal','reverberation 来自动词 reverberate。',1,'word-formation')]);
P('revere','Revere comes from Latin revereri, “stand in awe of, respect”; it means feel deep respect and admiration for someone or something.',C('revere.s1','崇敬；敬仰','Many residents revere the nurse who organized free clinics during the flood and stayed to care for patients.','许多居民敬仰这位护士，她在洪灾期间组织免费诊所并留下照顾病人。','Many residents revere the nurse / who organized free clinics / during the flood.','revere 指怀有深切尊敬和钦佩。','居民敬重为灾民服务的护士。'),M('The residents revered the nurse by mocking her work and refusing to acknowledge any respect for her.','The residents revered the nurse by honoring her work and expressing deep respect.','嘲笑并拒绝尊重与 revere 的敬仰义相反。','meaning'),[q('Why do residents revere the nurse?','she organized free clinics and cared for patients','she raised the currency exchange value','she opened a retrospective exhibition','居民敬仰护士，因为她组织诊所并照顾患者。',1,'context'),q('What does revere mean?','feel deep respect and admiration','take revenge for an injury','make an echo in a tunnel','revere 指深深尊敬并钦佩。',1,'meaning'),q('Which person might a community revere?','a doctor who devoted years to serving remote villages','a stranger who destroyed the village clinic','a clerk who refused to return borrowed books','长期服务偏远村庄的医生可能受到敬仰。',1,'context'),q('Which Latin verb is the source of revere?','revereri, “respect”','reverberare, “beat back”','revenir, “come back”','revere 源自拉丁语 revereri，含有敬重、敬畏之意。',1,'word-formation')]);
P('revered','Revered is the past participle of revere, from Latin revereri (“respect”); it describes someone or something regarded with great respect, often mixed with awe.',C('revered.s1','受崇敬的','The revered physician continued treating patients in the mountain village long after the temporary clinic closed.','这位受人敬仰的医生在临时诊所关闭后，仍继续为山村居民治病。','The revered physician continued treating patients / after the temporary clinic / had closed.','revered 描写受到深切尊敬、常带敬畏感的人或事物。','医生长期服务当地，因此受人敬仰。'),M('The revered physician was openly mocked by the villagers, who showed no respect for her work.','The revered physician was honored by the villagers for her years of service.','受到嘲笑且毫无尊重的人不能称为 revered。','meaning'),[q('Why was the physician revered?','she continued treating patients in the village','she closed the clinic and left at once','she reversed the court’s decision','医生在诊所关闭后继续服务，因此受人敬仰。',1,'context'),q('What does revered describe?','regarded with great respect','strongly criticized in public','able to be changed back','revered 指受到极大尊敬的。',1,'meaning'),q('Which person could be called revered?','a respected teacher honored by generations of former students','a stranger who insults everyone in the town','a reviewer who dislikes one book','受到几代学生尊敬的教师可以称为 revered。',1,'context'),q('Which verb is revered formed from?','revere','revert','reveal','revered 是动词 revere 的过去分词，也可作形容词。',1,'word-formation')]);
P('reverence','Reverence comes from Latin reverentia, from revereri (“stand in awe of”); it means deep respect or a solemn respectful manner.',[C('reverence.s1','尊敬；敬畏','The community spoke of the old lighthouse with reverence because it had guided generations of ships safely home.','由于这座古老灯塔曾为几代船只指引安全归途，社区居民怀着敬意谈起它。','The community spoke of the lighthouse / with reverence / because it had guided ships home.','reverence.s1 指深切的尊敬和钦佩。','灯塔长期守护船只，居民对它心怀敬意。'),C('reverence.s2','虔诚；恭敬的态度','The visitors entered the memorial hall in reverence, speaking softly and pausing before the names on the wall.','参观者怀着肃穆的敬意走进纪念堂，轻声交谈，并在墙上的姓名前驻足。','The visitors entered the hall in reverence / speaking softly / before the memorial wall.','reverence.s2 指行为中庄重而恭敬的态度。','参观者在纪念堂内保持肃穆。')],M('The visitors entered the memorial in reverence by shouting jokes and treating the names on the wall as a game.','The visitors entered the memorial in reverence by speaking quietly and honoring the names on the wall.','喧闹戏谑地对待纪念场所与庄重恭敬相反。','meaning'),[q('Why did residents speak of the lighthouse with reverence?','it had guided generations of ships safely home','it had reversed the sea’s direction','it had reviewed the ships’ books','灯塔为几代船只指引归途，因此居民心怀敬意。',1,'context'),q('How did visitors behave in the memorial hall?','they spoke softly and paused before the names','they shouted jokes and ran through the hall','they revised a science exam','参观者轻声交谈并在姓名墙前驻足，表现出庄重敬意。',2,'context'),q('What does reverence mean in the lighthouse example?','deep respect and admiration','a written review of the lighthouse','a legal decision being cancelled','此处 reverence 指深深的尊敬与敬仰。',1,'meaning'),q('What does “in reverence” describe in the memorial sentence?','a solemn respectful manner','an official change to a decision','a new version of a book','in reverence 描写庄重恭敬的行为态度。',2,'meaning')]);
P('reverent','Reverent comes from Latin reverentem, from revereri (“respect”); it describes a person or behavior showing profound respect.',C('reverent.s1','恭敬的；尊敬的','The children listened in reverent silence as the elder described how the village was founded.','长者讲述村庄的建立经过时，孩子们怀着敬意静静聆听。','The children listened in reverent silence / as the elder described / the village’s founding.','reverent 描写表现出深切尊敬的态度或行为。','孩子们安静地尊敬聆听长者。'),M('The children showed a reverent attitude by interrupting the elder with loud jokes and refusing to listen.','The children showed a reverent attitude by listening quietly and respectfully to the elder.','大声打断且拒绝聆听并非恭敬的态度。','meaning'),[q('How did the children listen to the elder?','in respectful silence','while shouting jokes','while writing a product review','孩子们怀着敬意静静听长者讲述。',1,'context'),q('What does reverent mean?','feeling or showing profound respect','carelessly changing a plan','likely to be cancelled','reverent 表示怀有或表现出深切尊敬。',1,'meaning'),q('Which behavior is reverent at a memorial?','standing quietly to honor those remembered','laughing loudly during a moment of silence','reversing the names on the wall','在纪念活动中肃立致敬是恭敬的行为。',1,'context'),q('Which related noun names the feeling of respect?','reverence','reversal','revenue','reverent 的相关名词 reverence 表示敬意。',1,'word-formation')]);
P('reverently','Reverently is formed from reverent and -ly; it means in a manner that shows solemn respect.',C('reverently.s1','恭敬地；虔诚地','The archivist reverently unfolded the fragile letter and placed it beneath a protective sheet.','档案管理员恭敬地展开那封易碎的信，并把它放在保护膜下。','The archivist reverently unfolded the letter / and placed it / beneath a protective sheet.','reverently 修饰动作，表示动作带着庄重敬意。','管理员小心而恭敬地处理旧信。'),M('The archivist handled the fragile letter reverently by tearing it carelessly and laughing at its contents.','The archivist handled the letter reverently by opening it carefully and preserving it.','粗暴撕毁并嘲笑内容不是恭敬的处理方式。','meaning'),[q('How did the archivist unfold the letter?','with solemn care and respect','by tearing it carelessly','while reversing its words','档案管理员恭敬地展开信件并妥善保护。',1,'context'),q('What does reverently tell us about the action?','it was done with respect','it was done again for practice','it was done to cancel a decision','reverently 表示动作以恭敬的方式完成。',1,'meaning'),q('Which action might be done reverently?','placing a historic medal gently in its case','throwing an honored medal onto the floor','rewriting a receipt in haste','轻轻将历史勋章放入展柜体现 reverently。',1,'context'),q('What is the base adjective in reverently?','reverent','reversed','revenue','reverently 由形容词 reverent 加 -ly 构成。',1,'word-formation')]);
P('reverie','Reverie came through French rêverie, “daydreaming”; its deeper history is uncertain, and it means a calm, pleasant state of absorbed thought.',C('reverie.s1','白日梦；出神','During the train ride, Nora slipped into a reverie and imagined the garden she would plant at her new home.','乘火车时，诺拉陷入遐想，想象自己将在新家种植的花园。','Nora slipped into a reverie / and imagined / a garden at her new home.','reverie 指平静愉快地沉浸在自己的想法中。','诺拉出神地想象未来的花园。'),M('Nora was in a reverie while she focused only on the train timetable and thought about nothing else.','Nora was in a reverie while her thoughts drifted to an imagined garden.','专注读时刻表而没有沉浸遐想，不符合 reverie。','meaning'),[q('What did Nora imagine during her reverie?','a garden at her new home','a reversal of the train timetable','a review of an old lighthouse','诺拉在遐想中想象了新家的花园。',1,'context'),q('What is a reverie?','a calm, pleasant state of absorbed thought','a loud party for former classmates','a formal review by a court','reverie 指平静愉快的出神遐想。',1,'meaning'),q('Which moment is a reverie?','a passenger gazes out the window while imagining a future trip','a driver checks each road sign carefully','a reviewer writes a detailed critique','乘客望窗出神并想象未来旅行属于 reverie。',1,'context'),q('What is known about the deeper origin of reverie?','it is uncertain','it definitely comes from Latin revertere','it is formed from review and -er','reverie 经法语传入，其更深层词源并不确定。',1,'word-formation')]);
P('reversal','Reversal is formed from reverse and -al; it means a change into the opposite, a setback that turns success into defeat, or a higher court’s cancellation of a verdict.',[C('reversal.s1','颠倒；反转','The reversal of the route meant that runners now traveled from the coast toward the hills.','路线反转后，选手现在从海岸向山地跑。','The reversal of the route meant / runners now traveled / from coast to hills.','reversal.s1 指次序或方向变成相反状态。','赛道方向被调转。'),C('reversal.s2','挫折；败局','After leading for most of the match, the team suffered a sudden reversal when its goalkeeper was injured.','球队在大部分比赛中领先，却因守门员受伤而突然遭遇挫败。','The team suffered a reversal / after leading / for most of the match.','reversal.s2 指使早先成功转为失利的挫折。','领先球队因伤病陷入败局。'),C('reversal.s3','（判决的）推翻','The appeals court’s reversal of the verdict required a new trial.','上诉法院推翻原判后，案件需要重新审理。','The appeals court’s reversal of the verdict / required / a new trial.','reversal.s3 指上级法院正式撤销先前判决。','原判被上诉法院推翻。')],M('The appeals court announced a reversal of the verdict but left the earlier decision fully in force without changing it.','The appeals court announced a reversal of the verdict and cancelled the earlier decision.','若旧判决仍完全有效，就没有发生推翻。','meaning'),[q('Which way did runners travel after the route reversal?','from the coast toward the hills','from the hills toward the coast','from the courthouse to the stadium','路线反转后，选手从海岸向山地跑。',1,'context'),q('Why did the team suffer a reversal?','its goalkeeper was injured after it had led','it won every remaining point','its route was changed before the race','球队原先领先，却因守门员受伤遭遇挫败。',2,'context'),q('What did the appeals court do?','cancelled the earlier verdict','held a reunion for the judges','raised the city’s revenue','上诉法院推翻原判，要求重新审理。',1,'meaning'),q('Which sentence uses reversal to mean a setback?','A late injury turned the leader’s advantage into defeat.','The runners changed direction and followed the reversed route.','The appeals court cancelled the verdict.','最后的受伤使领先变成失败，属于挫折意义的 reversal。',2,'meaning')]);
P('reverse','Reverse comes through Old French reverser from Latin reversus, past participle of revertere (“turn back”); it can change direction or a decision, mean drive backward, name an opposite/back side, or describe an opposite position.',[C('reverse.s1','颠倒；反向；撤销','The committee voted to reverse its earlier decision after receiving new safety evidence.','收到新的安全证据后，委员会投票撤销了先前的决定。','The committee voted to reverse its decision / after receiving / new safety evidence.','reverse.s1 指使方向、次序或决定变成相反状态。','新证据促使委员会撤销旧决定。'),C('reverse.s2','倒车；倒挡','The driver put the van in reverse to back out of the narrow driveway.','司机挂倒挡，把面包车倒出狭窄的车道。','The driver put the van in reverse / to back out / of the narrow driveway.','reverse.s2 可作名词表示倒挡，也可表示向后行驶。','司机挂倒挡驶出车道。'),C('reverse.s3','相反情况；背面','The reverse of the postcard shows the address and a short handwritten message.','明信片背面写着地址和一小段手写留言。','The reverse of the postcard shows / the address / and a short message.','reverse.s3 可指相反面或相反情况。','明信片背面有地址和留言。'),C('reverse.s4','相反的；背面的','The reverse side of the medal carries the year and the maker’s mark.','奖章的背面刻有年份和制造商标记。','The reverse side of the medal carries / the year / and the maker’s mark.','reverse.s4 作形容词，表示背面的或方向相反的。','奖章背面刻有信息。')],M('The committee reversed its decision by keeping the original rule unchanged after new evidence arrived.','The committee reversed its decision by cancelling the original rule after considering new evidence.','保留原决定不变不是撤销或改变它。','meaning'),[q('Why did the committee reverse its decision?','new safety evidence arrived','the van needed a new tire','the postcard was mailed','委员会收到新的安全证据后撤销旧决定。',1,'context'),q('What did the driver select to back out?','reverse gear','the medal’s reverse side','a retrospective review','司机挂倒挡驶出狭窄车道。',2,'context'),q('Where is the postcard address written?','on the reverse of the postcard','on the medal’s front','inside the van’s engine','地址写在明信片背面。',3,'context'),q('In “the reverse side of the medal,” what part of speech is reverse?','adjective describing the back side','verb cancelling a decision','noun meaning a setback','这里 reverse 是形容词，指奖章背面。',4,'meaning')]);
P('reversed','Reversed is the past participle of reverse; it describes an order, direction, or position changed to its opposite.',C('reversed.s1','颠倒的；反向的','The reversed seating plan placed the orchestra behind the audience instead of in front of it.','颠倒后的座位安排把乐团放在观众后方，而不是前方。','The reversed seating plan placed the orchestra / behind the audience / instead of in front.','reversed 描写原有次序或方向已经变成相反状态。','乐团与观众的前后位置被调换。'),M('The seating plan was reversed because every person and section remained in exactly its original place.','The seating plan was reversed because the orchestra and audience switched positions.','位置完全没变就不能称为 reversed。','meaning'),[q('Where did the reversed plan place the orchestra?','behind the audience','in front of the audience','inside the ticket office','颠倒后的安排把乐团放到观众后面。',1,'context'),q('What does reversed describe?','changed to an opposite order or direction','deeply respected','used again without change','reversed 表示次序或方向被调转。',1,'meaning'),q('Which map is reversed?','one that swaps east and west from the original','one that preserves every direction','one that displays a reviewer’s comments','把东西方向与原图调换的地图是 reversed。',1,'context'),q('Which verb is the base of reversed?','reverse','reverence','revenue','reversed 是 reverse 的过去分词。',1,'word-formation')]);
P('reversible','Reversible comes from Latin reversibilis, from revertere (“turn back”); it means capable of returning to an earlier state, officially being cancelled, or being worn on either side.',[C('reversible.s1','可逆的；可恢复的','The chemical change is reversible: cooling the solution restores its original color.','这种化学变化是可逆的：冷却溶液会使它恢复原来的颜色。','The change is reversible / because cooling the solution / restores its original color.','reversible.s1 指能够恢复到先前状态。','冷却后溶液恢复原色。'),C('reversible.s2','可撤销的','The temporary license is reversible, so the agency can cancel it if the applicant breaks the conditions.','这项临时执照可以撤销，因此申请人违反条件时，机构能够取消它。','The license is reversible / so the agency can cancel it / if conditions are broken.','reversible.s2 指决定或授权可以正式撤回。','违反条件后执照可被取消。'),C('reversible.s3','双面可穿的','She packed a reversible jacket whose blue side suited the daytime walk and whose gray side suited the evening concert.','她带了一件双面夹克，蓝色一面适合白天散步，灰色一面适合晚间音乐会。','She packed a reversible jacket / with a blue side for daytime / and gray for evening.','reversible.s3 指衣服两面都可以朝外穿。','夹克可以翻面穿着。')],M('The color change was reversible because cooling the solution could not restore its earlier color under any condition.','The color change was reversible because cooling the solution restored its earlier color.','不能恢复原状的变化不是可逆变化。','meaning'),[q('How can the solution’s original color be restored?','by cooling it','by cancelling a license','by turning a jacket inside out','冷却溶液后，原来的颜色会恢复。',1,'context'),q('Why can the agency revoke the license?','the authorization is reversible under its conditions','the license is a reversible jacket','the applicant filed a review','违反条件时，机构可以取消这项可撤销的执照。',2,'context'),q('What makes the jacket reversible?','either side can be worn facing outward','it can return to its shop by itself','it has two sleeves of different lengths','夹克两面都能朝外穿，因此是双面可穿的。',3,'context'),q('What is the core idea of reversible in the chemical example?','able to return to an earlier state','already changed permanently','officially praised with respect','reversible 的核心意思是可以恢复到先前状态。',1,'meaning')]);
P('reversion','Reversion comes from Latin reversio, from revertere (“turn back”); it means a change back to an earlier condition, practice, or state.',C('reversion.s1','回复；逆转','The reversion to paper records happened after the online system repeatedly lost customer files.','在线系统反复丢失客户文件后，公司又改回纸质记录。','The reversion to paper records happened / after the online system / lost files repeatedly.','reversion 指回到以前的状态或做法。','公司从线上系统退回纸质档案。'),M('The company’s reversion to paper records meant it abandoned paper and continued using the same online system.','The company’s reversion to paper records meant it returned to its earlier paper-based practice.','继续使用线上系统并不构成回到旧做法。','meaning'),[q('Why did the company return to paper records?','the online system repeatedly lost files','the paper records had never existed','the reviewers requested a reunion','线上系统反复丢失文件，促使公司改回纸质记录。',1,'context'),q('What does reversion mean?','a change back to an earlier condition','a first move into a new condition','a detailed opinion about a film','reversion 指回复到先前状态。',1,'meaning'),q('Which event is a reversion?','a town restores its old voting method after a trial period','a town adopts a method for the first time','a court reverses a verdict once','试行后恢复旧投票方式属于 reversion。',1,'context'),q('Which Latin verb is linked to reversion?','revertere, “turn back”','revereri, “respect”','revelare, “unveil”','reversion 与 revertere（转回去）有关。',1,'word-formation')]);
P('revert','Revert comes from Latin revertere, “turn back”; it means return to a previous condition, practice, or subject, and property can revert to a former owner.',[C('revert.s1','恢复原状；回到原话题','If the new software causes errors, the team will revert to the previous version while it investigates.','如果新软件引发错误，团队会在调查期间恢复到旧版本。','The team will revert to the previous version / if the new software / causes errors.','revert.s1 指恢复先前状态、做法或回到原话题。','团队会暂时退回旧版本。'),C('revert.s2','（财产或权利）归还','If the lease ends without renewal, the garden plot will revert to the landowner.','如果租约到期未续，花园地块将归还土地所有者。','The garden plot will revert to the landowner / if the lease / is not renewed.','revert.s2 指财产或权利回到原所有者。','租约未续时地块归还地主。')],M('After errors appeared, the team reverted to the new version and refused to return to the earlier software.','After errors appeared, the team reverted to the previous version while investigating the problem.','revert to the previous version 表示回到旧版本，错误句却继续使用新版本。','meaning'),[q('What will the team do if the new software causes errors?','return to the previous version','reunite the software developers','revalue the city’s houses','出现错误时，团队会退回到旧版本。',1,'context'),q('Who will receive the garden plot if the lease is not renewed?','the landowner','the former tenant’s reviewer','the city’s revenue office','租约未续时，花园地块归还土地所有者。',2,'context'),q('What does revert mean in “revert to the previous version”?','return to an earlier state','make an earlier decision permanent','reveal a hidden fact','这里 revert 指恢复到较早的状态。',1,'meaning'),q('What does revert mean when property reverts?','go back to a former owner','be reviewed by a critic','be worn on either side','财产 revert 指归还给原所有者。',2,'meaning')]);
P('review','Review comes from re- and view (“see again”); it can mean study or think about something again, officially examine it, or publish an opinion of a book, film, or product.',[C('review.s1','复习；回顾','Mina reviewed her notes each evening so she could remember the key terms before the biology exam.','米娜每晚复习笔记，以便在生物考试前记住关键术语。','Mina reviewed her notes / each evening / before the biology exam.','review.s1 指再次学习材料或回顾过去事件。','学生反复复习笔记。'),C('review.s2','审查；复核','The safety board will review the factory’s procedures after the alarm failed during the drill.','演习期间警报失灵后，安全委员会将审查工厂的流程。','The safety board will review the procedures / after the alarm / failed during the drill.','review.s2 指正式检查并判断是否需要修改。','委员会正式审查安全流程。'),C('review.s3','评论；书评；影评','The newspaper published a review of the documentary, praising its clear interviews but criticizing its slow ending.','报纸刊登了这部纪录片的评论，称赞采访清晰，同时批评结尾节奏缓慢。','The newspaper published a review / praising the interviews / but criticizing the ending.','review.s3 指表达对书、电影或产品看法的评论文章或谈话。','影评同时写出优点和缺点。')],M('The safety board reviewed the procedures by refusing to examine them and leaving the failed alarm uninvestigated.','The safety board reviewed the procedures by examining how the alarm failed during the drill.','拒绝检查流程不符合正式审查的意思。','meaning'),[q('What did Mina do each evening?','studied her notes again','published a film critique','reversed the exam results','米娜每晚复习笔记准备考试。',1,'context'),q('Why will the safety board review procedures?','the alarm failed during a drill','the newspaper praised a documentary','Mina returned to the village','警报在演习中失灵，因此委员会要审查流程。',2,'context'),q('What did the newspaper publish?','an opinion about a documentary','a tax return for the factory','a reunion invitation','报纸刊登了纪录片评论。',3,'context'),q('Which use of review means examine officially?','The board reviewed the factory’s safety procedures.','Mina reviewed vocabulary for the exam.','A critic reviewed the documentary.','第一句 review 指正式检查安全流程。',1,'meaning')]);
P('reviewer','Reviewer is formed from review and the agent suffix -er; it means a person who evaluates books, performances, products, or academic work.',C('reviewer.s1','评论者；审稿人','The reviewer praised the novel’s vivid setting but noted that its final chapter resolved the mystery too quickly.','评论者称赞小说生动的背景描写，同时指出最后一章解谜过快。','The reviewer praised the setting / but noted / the quick ending.','reviewer 指撰写或进行评论、评审的人。','评论者评价小说优缺点。'),M('The reviewer evaluated no book, performance, product, or paper and only repaired the theater’s stage lights.','The reviewer evaluated the novel and described both its strengths and its weak ending.','没有进行任何评价的人不能称为 reviewer。','meaning'),[q('What did the reviewer praise?','the novel’s vivid setting','the factory’s alarm failure','the return of the old software','评论者称赞了小说生动的背景描写。',1,'context'),q('What weakness did the reviewer note?','the mystery was resolved too quickly','the setting was too vivid','the novel had been reused','评论者指出小说最后一章解谜太快。',1,'context'),q('What is a reviewer?','a person who evaluates or comments on work','a person who returns property to its owner','a person who restores vegetation','reviewer 指评论或评审作品的人。',1,'meaning'),q('What does the suffix -er indicate in reviewer?','a person who performs an activity','a state of returning','the quality of being reversible','-er 在 reviewer 中表示从事评论的人。',1,'word-formation')]);
P('revile','Revile came through French reviler, “treat with contempt”; its deeper history is uncertain, and it means abuse someone cruelly or denounce something fiercely in public.',[C('revile.s1','辱骂；谩骂','Online commenters reviled the volunteer with personal insults instead of discussing the rescue plan.','网上评论者用人身侮辱谩骂这名志愿者，而不是讨论救援计划。','Commenters reviled the volunteer / with personal insults / instead of discussing the plan.','revile.s1 指用残酷、侮辱性的话辱骂某人。','评论者针对志愿者进行人身攻击。'),C('revile.s2','公开抨击','The columnist reviled the proposal in public, calling it costly and harmful to small businesses.','专栏作者公开抨击这项提案，称其成本高昂且会损害小企业。','The columnist reviled the proposal / in public / as costly and harmful.','revile.s2 指在公共场合猛烈批评某事。','专栏作者公开批评提案。')],M('The commenters reviled the volunteer by thanking her politely for the rescue work and avoiding every insult.','The commenters reviled the volunteer by attacking her with cruel personal insults.','礼貌感谢且没有侮辱不是 revile。','meaning'),[q('How did commenters revile the volunteer?','with personal insults','by thanking her politely','by reviewing her book','评论者以人身侮辱谩骂志愿者。',1,'context'),q('How did the columnist treat the proposal?','denounced it publicly as harmful','praised it privately as perfect','reversed it into a garden','专栏作者公开抨击该提案。',2,'context'),q('Which meaning of revile appears in the volunteer example?','abuse a person with cruel language','criticize a policy in public','respect someone deeply','此处 revile 指用恶毒语言辱骂某人。',1,'meaning'),q('What is known about revile’s deeper etymology?','it is uncertain','it comes from Latin reverentia','it is certainly formed from re- and view','revile 由法语传入，其更深层来源不确定。',1,'word-formation')]);
P('revise','Revise came through French réviser from Latin revisere, “look at again”; it means alter a text, plan, or estimate, and in British English it can mean study again for an exam.',[C('revise.s1','修订；修改','The engineers revised the bridge plan after the survey showed that the riverbed was deeper than expected.','调查显示河床比预想更深后，工程师修改了桥梁方案。','The engineers revised the plan / after the survey showed / a deeper riverbed.','revise.s1 指修改文本、计划或估算。','工程师根据调查结果调整方案。'),C('revise.s2','复习（英式英语）','In Britain, Sam revises vocabulary with flash cards each night before his language exam.','在英国，萨姆每天晚上用抽认卡复习词汇，准备语言考试。','Sam revises vocabulary / with flash cards / before his language exam.','revise.s2 在英式英语中也表示为考试复习。','学生使用抽认卡备考。')],M('The engineers revised the bridge plan by copying it unchanged despite the new survey results.','The engineers revised the bridge plan by changing it to account for the deeper riverbed.','照抄旧计划而不根据新信息修改，不是 revise。','meaning'),[q('Why did engineers revise the bridge plan?','the riverbed was deeper than expected','the flash cards had been lost','the reviewer disliked a novel','新调查发现河床更深，工程师因此修改方案。',1,'context'),q('What does Sam do before his language exam in British usage?','studies vocabulary again','cancels the exam results','returns borrowed cards to a library','英式用法中，Sam 为考试复习词汇。',2,'context'),q('What does revise mean in “revise a plan”?','change it after reconsideration','study it for the first time','insult it in public','revise a plan 指重新考虑后修改计划。',1,'meaning'),q('Which Latin verb is connected with revise?','revisere, “look at again”','revertere, “turn back”','revelare, “unveil”','revise 与拉丁语 revisere（再看一遍）有关。',1,'word-formation')]);
P('revised','Revised is the past participle of revise; it describes a text, plan, or estimate changed from an earlier version.',C('revised.s1','修订过的','The revised schedule moved the final inspection to Monday after the delivery was delayed.','交货延期后，修订后的日程把最终检查改到了星期一。','The revised schedule moved the inspection / to Monday / after the delivery delay.','revised 描写已经根据新情况修改过的内容。','检查日期因交货延误而修改。'),M('The revised schedule was called revised even though it was copied exactly and no dates or details changed.','The revised schedule was called revised because the inspection date had been changed to Monday.','所有日期和细节保持原样，就没有经过修订。','meaning'),[q('What changed in the revised schedule?','the final inspection moved to Monday','the bridge plan returned to its original draft','the reviewer changed the novel’s ending','修订后的日程把最终检查改到星期一。',1,'context'),q('What does revised describe?','changed from an earlier version','never altered from its first version','able to be worn on either side','revised 指经过修改的版本。',1,'meaning'),q('Which item is revised?','a budget updated after new costs arrive','a form copied with every figure unchanged','a plan that has not been reviewed','收到新成本后更新的预算是 revised budget。',1,'context'),q('Which verb is revised derived from?','revise','revere','reveal','revised 是 revise 的过去分词形式。',1,'word-formation')]);
P('revision','Revision comes from Latin revisio, from revisere (“look at again”); it means the act of changing writing, a changed version, or (in British English) exam study.',[C('revision.s1','修订；修改行为','The revision of the safety manual clarified who should call emergency services during a chemical spill.','安全手册的修订明确了发生化学品泄漏时谁应联系急救部门。','The revision of the manual clarified / who should call / emergency services.','revision.s1 指修改和完善文本的行为。','手册修订后职责更清楚。'),C('revision.s2','修订版','The second revision of the guide includes a map that was missing from the original edition.','指南的第二个修订版加入了初版中缺失的地图。','The second revision of the guide includes / a map / missing from the first edition.','revision.s2 可指修改后形成的新版本。','新版指南补上了地图。'),C('revision.s3','复习（英式英语）','Her evening revision covered the dates and causes most likely to appear on the history exam.','她晚上的复习涵盖了历史考试最可能考到的日期和原因。','Her evening revision covered / likely dates and causes / for the history exam.','revision.s3 在英式英语中也指备考复习。','学生复习历史考试重点。')],M('The revision of the manual left every unclear instruction unchanged and added no clarification.','The revision of the manual clarified the instructions for responding to a chemical spill.','完全不修改也不澄清内容不是修订。','meaning'),[q('What did the safety-manual revision clarify?','who should call emergency services','which film received the best review','where the hikers should return','手册修订说明了泄漏事故时谁应联系急救部门。',1,'context'),q('What did the second revision add to the guide?','a map missing from the original','a new language exam','a different tax return','指南的第二个修订版补上了初版缺失的地图。',2,'context'),q('In British usage, what can evening revision mean?','study done for an exam','a new printed version of a manual only','a public attack on a proposal','英式用法中 evening revision 可以指备考复习。',3,'meaning'),q('Which use of revision names the act of changing a text?','the revision clarified the instructions','the second revision contains a new map','she did revision before the exam','第一句的 revision 指修改文本这一行为。',1,'meaning')]);
P('revitalise','Revitalise is the British spelling of revitalize, formed from re- and vitalize (from Latin vita, “life”); it means make a person, place, or organization lively and successful again.',C('revitalise.s1','使重新有活力；振兴','The council hopes to revitalise the empty market by inviting local cooks and craftspeople to open stalls.','市议会希望邀请当地厨师和手工艺人设摊，让空荡荡的集市重新兴旺起来。','The council hopes to revitalise the market / by inviting local vendors / to open stalls.','revitalise 指使地方、组织或人重新充满活力。','新摊位计划为集市注入活力。'),M('The council revitalised the market by closing every stall permanently and discouraging visitors from returning.','The council revitalised the market by attracting vendors and bringing shoppers back.','永久关闭摊位并赶走顾客会使集市衰败，而非振兴。','meaning'),[q('How will the council try to revitalise the market?','invite local vendors to open stalls','close every stall permanently','reverse the exchange rate','市议会计划吸引当地摊贩，让集市重新兴旺。',1,'context'),q('What does revitalise mean?','make lively and successful again','make a previous decision legally reversible','study for an exam again','revitalise 指使某人或某地重新有活力。',1,'meaning'),q('Which project would revitalise a town center?','bringing shops and community events back to empty streets','removing the last business and blocking visitors','publishing a review of the town’s past','让商店和社区活动回到空荡街区可振兴市中心。',1,'context'),q('Which spelling is British?','revitalise','reverberise','reversalyse','revitalise 是 revitalise/revitalize 这一词的英式拼法。',1,'word-formation')]);
P('revitalization','Revitalization is formed from revitalize and -ation; it names the act or process of bringing new life to an area, industry, or practice.',C('revitalization.s1','振兴；复兴','The revitalization of the harbor district began with safer walkways and grants for small businesses.','港口街区的振兴始于更安全的人行道和面向小企业的补助。','The revitalization of the harbor district began / with safer walkways / and business grants.','revitalization 指使地区、行业或做法恢复活力的过程。','公共设施和商业补助启动了街区振兴。'),M('The revitalization of the harbor district involved closing businesses, removing walkways, and making the area less active.','The revitalization of the harbor district involved improving walkways and helping local businesses reopen.','让地区更冷清、关闭商店与振兴的过程相反。','meaning'),[q('What began the harbor district’s revitalization?','safer walkways and grants for small businesses','the removal of every public walkway','a review of the old district map','更安全的人行道和企业补助启动了港口街区振兴。',1,'context'),q('What does revitalization name?','the process of bringing new life to a place or practice','a person who writes a review','a court’s cancellation of a verdict','revitalization 是使某地或做法恢复活力的过程。',1,'meaning'),q('Which example is revitalization?','restoring a declining neighborhood with services and new shops','closing all local shops without replacement','reverting to paper records after system errors','通过服务和新店让衰落社区重获活力属于 revitalization。',1,'context'),q('Which suffix helps form the noun revitalization?','-ation','-er','-ly','revitalize 加 -ation 构成表示过程的名词 revitalization。',1,'word-formation')]);
P('revitalize','Revitalize combines re- and vitalize, from Latin vita (“life”); it means make something active, healthy, or successful again.',C('revitalize.s1','使恢复生气；振兴','A new evening bus route could revitalize the waterfront by bringing visitors to restaurants after work.','新增的夜间公交线路可以把下班后的游客带到餐馆，从而振兴滨水区。','A new evening route could revitalize the waterfront / by bringing visitors / after work.','revitalize 指使地方或事物再次活跃、健康或成功。','交通改善能吸引游客并带旺滨水区。'),M('The bus route revitalized the waterfront by stopping all evening service and keeping visitors away from its restaurants.','The bus route revitalized the waterfront by bringing more evening visitors to local restaurants.','停止服务并赶走游客不会让滨水区恢复活力。','meaning'),[q('How could the new bus route revitalize the waterfront?','bring visitors to restaurants after work','prevent all visitors from reaching the area','replace the city’s annual tax return','夜间公交能把游客带到餐馆，促进滨水区复兴。',1,'context'),q('What does revitalize mean?','make active or successful again','change something into its opposite','describe an official review','revitalize 表示使某事物重新活跃或成功。',1,'meaning'),q('Which action could revitalize a struggling theater?','offer new shows and make it accessible to more residents','cancel all performances and lock the doors','reverse the order of its old programs without reopening','推出新演出并吸引居民可能让剧院恢复活力。',1,'context'),q('What does vita mean in the history of vitalize?','life','back','respect','vita 是拉丁语“生命”，与 revitalize 的活力含义有关。',1,'word-formation')]);
P('revival','Revival is formed from revive and -al; revive goes back to Latin revivere, “live again.” It can mean renewed popularity or a return to health or strength.',[C('revival.s1','复兴；重新流行','The revival of interest in traditional weaving led the town museum to offer weekend workshops.','传统编织重新受到欢迎后，镇上的博物馆开设了周末工作坊。','The revival of interest in weaving / led the museum / to offer workshops.','revival.s1 指某种风格、活动或观念重新流行。','传统编织再次流行并带来课程。'),C('revival.s2','复苏；恢复精力','After several weeks of rest and treatment, the athlete’s revival surprised her coach.','经过几周休息和治疗后，运动员的恢复令教练惊讶。','The athlete’s revival surprised her coach / after weeks / of rest and treatment.','revival.s2 指健康、力量或活力恢复。','运动员逐渐恢复体力。')],M('The athlete’s revival meant that she grew weaker each day and never regained any strength.','The athlete’s revival meant that her health and strength returned after treatment.','持续衰弱而未恢复体力不是复苏。','meaning'),[q('What did the revival of weaving interest lead the museum to offer?','weekend workshops','a new tax return','a card-game tournament','传统编织复兴后，博物馆开设了周末课程。',1,'context'),q('What surprised the coach?','the athlete’s return to health and strength','the loss of the weaving workshops','the revocation of a license','运动员经过休养后恢复体力令教练惊讶。',2,'context'),q('Which meaning of revival appears in the weaving example?','a return to popularity','a recovery from illness','a complete circular movement','这里 revival 指重新流行。',1,'meaning'),q('Which verb forms revival?','revive','revolve','reword','revival 由 revive 加 -al 构成。',1,'word-formation')]);
P('revive','Revive comes from Latin revivere, “live again,” formed with re- and vivere (“live”); it means regain consciousness or make something active and popular again.',[C('revive.s1','苏醒；使苏醒','The lifeguard used first aid to revive the swimmer, who had briefly lost consciousness in the pool.','游泳者在池中短暂失去意识后，救生员用急救措施使其苏醒。','The lifeguard used first aid / to revive the swimmer / after she lost consciousness.','revive.s1 指使失去意识的人恢复知觉，也可指自己苏醒。','急救使溺水者恢复意识。'),C('revive.s2','复兴；重新流行','The theater revived a forgotten comedy by staging a new production for younger audiences.','剧院为年轻观众排演新版本，使一部被遗忘的喜剧重新焕发生机。','The theater revived a forgotten comedy / with a new production / for younger audiences.','revive.s2 指使某物重新活跃、流行或强盛。','新演出使旧喜剧重新受到关注。')],M('The lifeguard revived the swimmer by refusing first aid while she remained unconscious.','The lifeguard revived the swimmer by giving first aid until she regained consciousness.','不施救且让人持续昏迷不属于使其苏醒。','meaning'),[q('What did first aid do for the swimmer?','helped her regain consciousness','made a forgotten comedy popular','cancelled the theater production','急救使泳池中的游泳者恢复意识。',1,'context'),q('How did the theater revive the comedy?','by staging a new production','by cancelling every performance','by returning a license','剧院通过新排演让旧喜剧重新活跃。',2,'context'),q('What does revive mean in the first example?','make an unconscious person conscious again','make an old show popular again','write an old play for the first time','第一句中的 revive 指使失去意识的人苏醒。',1,'meaning'),q('What is the Latin verb vivere related to in revive?','live','turn','call','revive 中的 vivere 意为“生活、活着”。',1,'word-formation')]);
P('reviver','Reviver is formed from revive and the agent suffix -er; it means a person or thing that restores life, interest, or energy.',C('reviver.s1','使复苏的人或物','The cold drink was a welcome reviver for the hikers after the steep climb in the summer heat.','炎热夏季爬完陡坡后，这杯冷饮让徒步者恢复了精神。','The cold drink was a welcome reviver / after the hikers / climbed in the heat.','reviver 指使人或事物恢复活力、兴趣或精神的人或物。','冷饮使疲惫的徒步者恢复精神。'),M('The cold drink was a reviver because it made the exhausted hikers even sleepier and less alert.','The cold drink was a reviver because it refreshed the hikers after their climb.','让人更疲倦而非恢复精神的东西不是 reviver。','meaning'),[q('When did the hikers drink the cold beverage?','after a steep climb in the heat','before they began a winter swim','during a court hearing','徒步者在炎热天气爬坡后喝了冷饮。',1,'context'),q('What did the drink do as a reviver?','refreshed the tired hikers','reversed the mountain route','reworded the climbing guide','冷饮让疲惫的徒步者恢复精神。',1,'context'),q('What is a reviver?','something that restores energy or interest','something that removes all energy','a person who writes a legal revision','reviver 指使人或物恢复活力的东西或人。',1,'meaning'),q('Which suffix marks the agent or thing in reviver?','-er','-al','-ion','revive 加 -er 构成表示施事者或事物的 reviver。',1,'word-formation')]);
P('revivification','Revivification comes from Latin revivificare, “make alive again”; it names the process of bringing a person, custom, or substance back to life or activity.',C('revivification.s1','恢复生机；复苏','The revivification of the neglected orchard began when volunteers pruned the trees and restored the irrigation channels.','志愿者修剪树木并修复灌溉渠后，这片荒废果园开始恢复生机。','The revivification of the orchard began / when volunteers pruned trees / and restored irrigation.','revivification 指使人、习俗或物质重新有生命力或活跃起来的过程。','果园经修整后重新焕发生机。'),M('The revivification of the orchard consisted of cutting down every tree and permanently blocking its water channels.','The revivification of the orchard involved pruning trees and restoring water to them.','砍光树木并断绝供水会破坏果园，而非使其复苏。','meaning'),[q('What began the orchard’s revivification?','pruning trees and restoring irrigation','blocking every water channel','reversing a court verdict','志愿者修剪树木、修复灌溉渠，使果园开始复苏。',1,'context'),q('What does revivification mean?','bringing something back to life or activity','ending an activity permanently','reviewing a past performance','revivification 指使事物恢复生机或活动。',1,'meaning'),q('Which project is revivification?','restoring a disused garden so it can grow again','paving over a garden and removing all plants','filing a tax return for a garden store','让废弃花园重新生长属于 revivification。',1,'context'),q('Which Latin verb is linked to revivification?','revivificare, “make alive again”','revertere, “turn back”','revereri, “respect”','revivification 与拉丁语 revivificare（使重新活起来）相关。',1,'word-formation')]);
P('revivify','Revivify comes from Latin revivificare, “make alive again,” with re- and a root related to vivere (“live”); it means restore life or vigor.',C('revivify.s1','使恢复生气；使复苏','A week of gentle rain helped revivify the dry meadow, and new shoots appeared among the grasses.','一周的和缓降雨使干旱的草甸恢复生气，草丛中冒出了新芽。','Gentle rain helped revivify the meadow / and new shoots / appeared among the grasses.','revivify 指使人、植物或事物恢复生命力。','降雨后草甸重新长出嫩芽。'),M('The rain revivified the meadow by drying the soil further and killing the remaining shoots.','The rain revivified the meadow by restoring moisture and encouraging new growth.','使土壤更干、嫩芽枯死不是恢复草甸生机。','meaning'),[q('What appeared after the rain?','new shoots among the grasses','a revised tax form','a new court verdict','降雨后草丛中长出了新芽。',1,'context'),q('What does revivify mean?','restore life or vigor','make something permanently lifeless','review something for an exam','revivify 指使事物恢复活力或生机。',1,'meaning'),q('Which action might revivify a dry garden?','watering it until new growth appears','removing all plants and sealing the soil','reversing the garden map','浇水使干旱花园长出新芽可以说 revivify。',1,'context'),q('What does the root vivi- in revivify relate to?','life','turning','speech','revivify 的词根与“生命、活着”有关。',1,'word-formation')]);
P('revocation','Revocation comes from Latin revocatio, from revocare (“call back”); it is the act of withdrawing a decree, license, or offer so that it is no longer valid.',C('revocation.s1','撤销；废止','The agency’s revocation of the permit followed repeated violations of the river-protection rules.','多次违反河流保护规定后，主管机构撤销了许可证。','The revocation of the permit followed / repeated violations / of river rules.','revocation 指正式收回许可、法令或提议，使其失效。','违规导致许可被撤销。'),M('The agency announced revocation of the permit but kept it fully valid and continued accepting it.','The agency announced revocation of the permit and made it no longer valid.','如果许可证仍完全有效，就没有发生撤销。','meaning'),[q('Why did the agency revoke the permit?','the holder repeatedly violated river rules','the permit was a reversible jacket','the agency wanted to revive a comedy','多次违反河流保护规定导致许可证被撤销。',1,'context'),q('What is revocation?','the act of withdrawing something so it is no longer valid','the act of granting a new permit','the act of reviewing old notes','revocation 指正式撤回并使其失效。',1,'meaning'),q('Which event is revocation?','a license is officially cancelled after a violation','a license is renewed for another year','a permit holder changes an address','违规后许可证被正式取消属于 revocation。',1,'context'),q('Which Latin verb is connected with revocation?','revocare, “call back”','revertere, “turn back”','revelare, “unveil”','revocation 来自 revocare，含有“召回、收回”之意。',1,'word-formation')]);
P('revoice','Revoice combines re- and voice; it means record new speech for a film or broadcast, or express an idea again in different words.',[C('revoice.s1','重新配音；重新表述','The studio will revoice the animated character after the original actor became unavailable.','原配音演员无法继续工作后，录音室将为动画角色重新配音。','The studio will revoice the character / after the original actor / became unavailable.','revoice.s1 指为影视或广播重新录制语音。','动画角色将由新演员重新配音。'),C('revoice.s1','重新表述','At the meeting, the chair revoiced the proposal in simpler terms so every resident could understand it.','会上，主席用更简单的话重新表述提案，让每位居民都能理解。','The chair revoiced the proposal / in simpler terms / for all residents.','revoice.s2 指用新的措辞再次表达想法。','主席换用简单措辞说明提案。')],M('The studio revoiced the cartoon by keeping the original recording untouched and adding no new speech.','The studio revoiced the cartoon by recording a new actor’s dialogue.','保留原录音且不添加新语音，不是重新配音。','meaning'),[q('Why will the studio revoice the animated character?','the original actor is unavailable','the original recording has already been replaced','the chair wants to cancel a permit','原配音演员无法继续工作，因此录音室需要重新配音。',1,'context'),q('How did the chair revoice the proposal?','by expressing it in simpler terms','by recording new dialogue for a cartoon','by revoking the proposal completely','主席用更简单的话重新表述提案。',1,'context'),q('What does revoice mean in a studio?','record new speech for a production','remove every voice from a broadcast','review an actor’s contract','录音室中的 revoice 指为作品重新录制语音。',1,'meaning'),q('What does revoice mean when a chair speaks?','say an idea again using different words','change the pitch of a recorded song only','take back an official license','重新表述提案中的 revoice 指换一种措辞再说一次。',1,'meaning')]);
P('revoke','Revoke comes from Latin revocare, “call back”; it can officially withdraw a license or right, cancel a decision or promise, or (in card games) fail to follow suit when able.',[C('revoke.s1','吊销（执照或权利）','The board voted to revoke the contractor’s license after inspectors documented repeated safety violations.','检查员记录到多次安全违规后，委员会投票吊销了承包商的执照。','The board voted to revoke the license / after inspectors documented / repeated violations.','revoke.s1 指正式收回执照或权利。','多次违规后执照被吊销。'),C('revoke.s2','废除；撤销决定或遗嘱','The donor decided to revoke the gift promise before the museum accepted the collection.','博物馆接受藏品前，捐赠者决定撤回赠与承诺。','The donor decided to revoke the promise / before the museum / accepted the collection.','revoke.s2 指取消决定、遗嘱或承诺，使之不再有效。','捐赠者撤回承诺。'),C('revoke.s3','（纸牌）藏牌','In a trick-taking card game, Leo revoked by playing a heart even though he still held a spade and spades were required.','在吃墩纸牌游戏中，虽然手里还有黑桃且该轮必须跟黑桃，利奥却出了红桃，构成藏牌。','Leo revoked by playing a heart / while still holding a spade / when spades were required.','revoke.s3 是纸牌术语，指有该花色时却未跟出。','玩家未按规定跟花色。')],M('The board revoked the license by leaving it valid and refusing to withdraw the contractor’s right to work.','The board revoked the license by officially cancelling the contractor’s right to work.','保留执照有效且不撤回权利，与 revoke 相反。','meaning'),[q('Why did the board revoke the contractor’s license?','inspectors documented repeated safety violations','the museum accepted a collection','the player held no spades','多次违规促使委员会吊销承包商执照。',1,'context'),q('What did the donor revoke?','a promise to give the collection','the contractor’s license','the player’s heart card','捐赠者在博物馆接收前撤回了赠与承诺。',2,'context'),q('Why was Leo said to have revoked in the card game?','he failed to follow suit while holding the required suit','he played a spade when hearts were required','he officially cancelled a license','利奥有黑桃却未跟黑桃，违反跟花色规则。',3,'context'),q('Which use of revoke means cancel an official right?','The board revoked the contractor’s license.','The donor revoked a promise before acceptance.','Leo revoked by failing to follow suit.','第一句中的 revoke 指吊销正式执照。',1,'meaning')]);
P('revolt','Revolt comes through French révolter from Latin revolvere (“roll back/turn back”); it can name an uprising, mean rise violently against authority, or make someone feel disgust.',[C('revolt.s1','起义；叛乱','The revolt began when the garrison refused to obey the ruler and townspeople joined the protest.','驻军拒绝服从统治者、镇民加入抗议后，起义爆发了。','The revolt began / when the garrison refused obedience / and townspeople joined.','revolt.s1 作名词，指反抗统治者或政府的行动。','驻军和镇民共同反抗统治者。'),C('revolt.s2','反叛；起义','Several provinces revolted against the central government after years of imposed taxes.','多年被强征税款后，几个省份起兵反抗中央政府。','Several provinces revolted / against the central government / after years of taxes.','revolt.s2 作动词，指以暴力行动反抗权威。','多个省份起兵反抗政府。'),C('revolt.s3','使厌恶；使反感','The spoiled food revolted the inspectors, who immediately ordered the kitchen closed.','变质食物让检查员感到恶心，他们立即下令关闭厨房。','The spoiled food revolted the inspectors / who immediately / closed the kitchen.','revolt.s3 指使某人产生强烈厌恶感。','变质食物令检查员反感。')],M('The provinces revolted against the ruler by obeying every order and peacefully accepting all imposed taxes.','The provinces revolted against the ruler by rising up in violent opposition.','服从命令且接受税收与起义反抗相反。','meaning'),[q('What triggered the revolt in the first example?','the garrison refused to obey and townspeople joined','the kitchen inspectors closed a restaurant','the theater revived a comedy','驻军拒绝服从、镇民加入抗议后起义爆发。',1,'context'),q('What did several provinces do?','rose against the central government','reversed the route to the coast','revoked a donor’s promise','几个省份起兵反抗中央政府。',2,'context'),q('What effect did the spoiled food have on inspectors?','it disgusted them','it gave them a reward','it made them revoice a proposal','变质食物使检查员感到厌恶。',3,'context'),q('Which use of revolt means “feel disgust”?','The smell revolted the visitors.','The citizens began a revolt.','The provinces revolted against the ruler.','第一句中的 revolt 表示使人感到恶心或厌恶。',1,'meaning')]);
P('revolution','Revolution comes from Latin revolutio, from revolvere (“roll back/around”); it can mean a political overthrow, a radical change, or one complete circular movement.',[C('revolution.s1','革命','The revolution replaced the monarchy with an elected government after months of popular uprising.','数月民众起义后，这场革命以民选政府取代了君主制。','The revolution replaced the monarchy / with an elected government / after the uprising.','revolution.s1 指民众试图改变政府、常以武力完成的革命。','起义推翻君主制并建立民选政府。'),C('revolution.s2','巨变；革命性变化','The shift to digital payments brought a revolution in how small shops manage daily sales.','数字支付的转变彻底改变了小商店管理日常销售的方式。','Digital payments brought a revolution / in how small shops / manage sales.','revolution.s2 指思想、工作或技术方面的巨大改变。','数字支付改变了商店经营方式。'),C('revolution.s3','旋转；环绕一周','One revolution of the wheel moves the conveyor belt forward by half a meter.','轮子转一整圈会使传送带前进半米。','One revolution of the wheel / moves the conveyor belt / half a meter.','revolution.s3 指绕某点完成一整圈旋转。','轮子每转一周，传送带移动半米。')],M('One revolution of the wheel meant that it stayed completely still and made no circular movement.','One revolution of the wheel meant that it completed a full circle.','轮子完全不动不是完成了一整圈旋转。','meaning'),[q('What government replaced the monarchy?','an elected government','a hereditary monarchy','a company board','革命后君主制被民选政府取代。',1,'context'),q('What did digital payments bring to small shops?','a major change in managing sales','a new political uprising','a circular wheel movement','数字支付给小商店的经营方式带来巨大变化。',2,'context'),q('How far does the conveyor belt move per wheel revolution?','half a meter','a full kilometer','no distance at all','轮子每转一周，传送带前进半米。',3,'context'),q('Which meaning of revolution is used in “a revolution in retail”?','a radical change','an uprising against a government','one complete turn of a wheel','零售业发生 revolution 指巨大变革。',2,'meaning')]);
P('revolutionary','Revolutionary is formed from revolution and -ary; as an adjective it means radically new, and as a noun it means a person seeking major political change.',[C('revolutionary.s1','革命性的；创新的','The team developed a revolutionary battery that charges in minutes and stores twice as much energy as earlier models.','团队研发出一种革命性电池，几分钟即可充电，储能量是旧型号的两倍。','The team developed a revolutionary battery / that charges quickly / and stores more energy.','revolutionary.s1 作形容词，指与以往相比彻底新颖的。','新电池的性能与旧型号大不相同。','形容词后缀 -ary 表示“具有……性质的”。'),C('revolutionary.s2','革命者','The revolutionary distributed pamphlets calling for an end to the military government.','这位革命者散发传单，号召结束军政府统治。','The revolutionary distributed pamphlets / calling for an end / to military rule.','revolutionary.s2 作名词，指主张重大政治变革的人。','传单呼吁结束军政府统治。')],M('The new battery was called revolutionary even though it charged more slowly and stored less energy than every earlier model.','The new battery was called revolutionary because it charged quickly and stored far more energy than earlier models.','性能落后于旧型号的产品不符合此处“革命性创新”的含义。','meaning'),[q('What makes the new battery revolutionary?','it charges quickly and stores twice as much energy','it takes days to charge and stores less energy','it is used to revoke a permit','新电池充电快且储能翻倍，因此被称为革命性产品。',1,'context'),q('What did the revolutionary distribute?','pamphlets opposing military rule','new battery cells','a reviewer’s book critique','革命者散发了反对军政府的传单。',2,'context'),q('In the battery sentence, is revolutionary a noun or adjective?','adjective describing a radical innovation','noun naming a political activist','adverb describing a repeated action','battery 前的 revolutionary 是形容词，表示创新。',1,'meaning'),q('In the pamphlet sentence, who is a revolutionary?','a person seeking major political change','a person reviewing a product','a wheel making one full turn','散发政治变革传单的人是名词 revolutionary。',2,'meaning')]);
P('revolutionize','Revolutionize is formed from revolution and -ize; it means transform a field, method, or industry completely.',C('revolutionize.s1','使发生革命性变化','Low-cost solar panels could revolutionize rural clinics by providing reliable power where the grid does not reach.','低成本太阳能板可为没有电网覆盖的乡村诊所提供稳定电力，从而彻底改变其运营方式。','Low-cost solar panels could revolutionize clinics / by providing reliable power / off the grid.','revolutionize 指使某领域或行业发生彻底改变。','太阳能供电可彻底改变偏远诊所的条件。'),M('The solar panels revolutionized the clinic by leaving its power supply and medical work completely unchanged.','The solar panels revolutionized the clinic by giving it reliable electricity for medical equipment.','条件完全未变就不能说发生了彻底改变。','meaning'),[q('How could solar panels revolutionize rural clinics?','provide reliable power beyond the grid','replace every nurse with a reviewer','reverse the clinic’s appointment list','太阳能板可为偏远诊所提供稳定电力。',1,'context'),q('What does revolutionize mean?','transform something completely','make a small adjustment without changing anything','return a permit to its owner','revolutionize 表示彻底改变某领域或方法。',1,'meaning'),q('Which invention could revolutionize farming?','a system that dramatically reduces water use while increasing yields','a tool that leaves farming exactly as it is','a report describing last year’s crops','大幅节水又提高产量的系统可能彻底改变农业。',1,'context'),q('Which suffix turns revolution into revolutionize?','-ize','-er','-ful','revolution 加 -ize 构成动词 revolutionize。',1,'word-formation')]);
P('revolve','Revolve comes from Latin revolvere, “roll back or around”; it means move in a circle around a center or have something as the main subject.',[C('revolve.s1','旋转；绕转','The small moon revolves around its planet once every thirty-two days.','这颗小卫星每三十二天绕行其行星一周。','The small moon revolves / around its planet / every thirty-two days.','revolve.s1 指围绕中心点作圆周运动。','卫星绕行行星。'),C('revolve.s2','围绕；以……为中心','The documentary revolves around three families adapting to life after the factory closes.','这部纪录片围绕三户家庭在工厂关闭后适应新生活的故事展开。','The documentary revolves around three families / adapting to life / after the factory closes.','revolve.s2 指故事或讨论以某主题为中心。','纪录片以三户家庭为核心。')],M('The moon revolves around its planet by remaining fixed in one place and never moving.','The moon revolves around its planet by moving in a circular path around it.','静止不动并非围绕行星作圆周运动。','meaning'),[q('How long does the moon take to revolve around its planet?','thirty-two days','one full year','one hour','这颗小卫星每三十二天绕行行星一周。',1,'context'),q('Who is the documentary about?','three families adapting after a factory closes','a revolutionary and a new government','a reviewer assessing a battery','纪录片围绕工厂关闭后适应生活的三户家庭展开。',2,'context'),q('What does revolve mean in the astronomy sentence?','move in a circle around a center','have a story as its central subject','cancel a right officially','天体 revolve around 行星指围绕其作圆周运动。',1,'meaning'),q('What does revolve around mean in the documentary sentence?','be mainly about','orbit physically around','be officially revoked by','纪录片 revolves around families 指以他们为主题。',2,'meaning')]);
P('revolver','Revolver is formed from revolve and -er; the firearm is named for its rotating cylinder, which holds several bullets.',C('revolver.s1','左轮手枪','The museum displayed an unloaded revolver in a locked case beside documents about the frontier period.','博物馆在边疆时期的文献旁，将一支未装弹的左轮手枪陈列在上锁展柜中。','The museum displayed an unloaded revolver / in a locked case / beside historical documents.','revolver 指带有旋转弹巢、可装多发子弹的手枪。','展出的枪支为带旋转弹巢的左轮手枪。'),M('The museum labeled a revolver a rotating-cylinder firearm even though it had no cylinder and held no cartridges.','The museum displayed a revolver with a cylinder that rotated to hold several bullets.','没有旋转弹巢的枪不符合 revolver 的结构特征。','meaning'),[q('Where was the revolver displayed?','in a locked museum case','on the town’s new bus route','inside the factory’s alarm panel','左轮手枪陈列在博物馆的上锁展柜中。',1,'context'),q('What feature defines a revolver?','a cylinder that turns to hold several bullets','a barrel that revolves around a planet','a wheel that moves a conveyor belt','左轮手枪的弹巢可以旋转以容纳多发子弹。',1,'meaning'),q('Was the displayed revolver loaded?','no, it was unloaded','yes, it was ready to fire','the case contained only a review','博物馆展出的左轮手枪没有装弹。',1,'context'),q('What does the -er ending suggest in revolver’s formation?','a device associated with revolving','a person who writes a review','a process of revocation','revolver 以可旋转的弹巢命名，与 revolve 有关。',1,'word-formation')]);
P('revulsion','Revulsion comes from Latin revulsio, from revellere (“pull away”); it means a sudden, intense feeling of disgust or hatred.',C('revulsion.s1','强烈的厌恶；反感','The inspectors felt revulsion at the spoiled meat and ordered the restaurant kitchen closed.','检查员看到变质肉类后感到强烈厌恶，并下令关闭餐馆厨房。','The inspectors felt revulsion / at the spoiled meat / and closed the kitchen.','revulsion 指突然产生的强烈厌恶或憎恶。','变质肉类令检查员非常反感。'),M('The inspectors felt revulsion toward the spoiled meat because it smelled fresh and looked appetizing.','The inspectors felt revulsion toward the spoiled meat because it smelled foul and appeared unsafe.','新鲜诱人的食物不会引起此处所说的强烈厌恶。','meaning'),[q('What caused the inspectors’ revulsion?','spoiled meat in the kitchen','a revolutionary battery','a moon orbiting its planet','检查员因厨房中的变质肉类而感到厌恶。',1,'context'),q('What is revulsion?','a sudden strong feeling of disgust','a mild interest in a topic','a repeated circular movement','revulsion 指强烈的厌恶感。',1,'meaning'),q('Which reaction shows revulsion?','someone recoils from a foul smell','someone admires a revered nurse','someone enjoys a weekend workshop','闻到恶臭后退缩体现 revulsion。',1,'context'),q('Which Latin verb is linked to revulsion?','revellere, “pull away”','revolvere, “roll around”','revertere, “turn back”','revulsion 与 revellere（拉开、扯离）有关。',1,'word-formation')]);
P('reward','Reward has an uncertain deeper history and came through Anglo-French rewarder in the sense of granting something in return; it names compensation or means give something for work, success, or help.',[C('reward.s1','报酬；奖赏；赏金','The family offered a reward for information that would help locate their missing dog.','这家人悬赏征集线索，希望找到走失的狗。','The family offered a reward / for information / about the missing dog.','reward.s1 指为工作、成功或帮助而给予的东西。','家人用赏金征集寻狗线索。'),C('reward.s2','奖赏；酬谢','The coach rewarded the players with an extra day of rest after their disciplined performance.','球员表现自律后，教练奖励他们多休息一天。','The coach rewarded the players / with an extra day of rest / after the match.','reward.s2 作动词，指因表现或帮助而给予回报。','教练以休息日奖励球员。')],M('The family offered a reward for information but promised that nobody who found the dog would receive anything.','The family offered a reward of money to anyone whose information helped find the dog.','承诺不给任何奖励却称为悬赏，与 reward 的回报含义冲突。','meaning'),[q('Why did the family offer a reward?','to get information about its missing dog','to punish the dog’s coach','to revoke the animal license','家人悬赏是为了征集走失狗的线索。',1,'context'),q('How did the coach reward the players?','with an extra day of rest','by reversing the match result','by making them revise the rules','教练奖励球员多休息一天。',2,'context'),q('What can a reward be?','something given in return for help or success','an official cancellation of a license','a strong feeling of disgust','reward 可指因帮助或成功而给予的回报。',1,'meaning'),q('In “the coach rewarded the players,” what part of speech is reward?','verb meaning gave them something in return','noun meaning a person’s deep respect','adjective meaning radically new','此处 rewarded 是动词，表示给予球员奖励。',1,'meaning')]);
P('rewarding','Rewarding is formed from reward and -ing; it describes work that gives satisfaction or an activity that produces a good return.',[C('rewarding.s1','值得做的；有回报的','Volunteering at the reading center was rewarding because the children grew more confident each week.','在阅读中心做志愿者很有成就感，因为孩子们每周都更自信。','Volunteering was rewarding / because the children / grew more confident.','rewarding.s1 指因觉得有用、有意义而令人满足的。','孩子进步让志愿服务有成就感。'),C('rewarding.s2','报酬优厚的；有利可图的','The consulting contract proved financially rewarding, paying enough to fund the firm’s new office.','这份咨询合同回报丰厚，收入足以支付公司的新办公室费用。','The contract proved financially rewarding / paying enough / for a new office.','rewarding.s2 指带来丰厚经济回报的。','合同收入为新办公室提供资金。')],M('Volunteering was rewarding because the children made no progress and the workers felt their efforts were useless.','Volunteering was rewarding because the children improved and the work felt useful.','没有进步且毫无意义的工作不符合令人满足的含义。','meaning'),[q('Why did the reading-center work feel rewarding?','the children grew more confident','the contract paid for a new office','the revocation ended the class','孩子每周更自信，让志愿服务很有成就感。',1,'context'),q('What did the consulting contract provide?','enough financial return for a new office','an extra day of rest for the players','a new version of the guide','咨询合同收入足以支付新办公室费用。',2,'context'),q('Which meaning of rewarding applies to volunteering?','giving satisfaction because the work feels useful','producing a large financial profit only','officially withdrawing a permit','志愿工作中的 rewarding 指有意义、令人满足。',1,'meaning'),q('Which use of rewarding refers to money?','a financially rewarding contract','a rewarding experience helping children','a rewarding conversation with a friend','financially rewarding 表示经济回报丰厚。',1,'meaning')]);
P('reword','Reword combines re- and word; it means express the same meaning in different words.',C('reword.s1','改说；换措辞','The editor asked the scientist to reword the abstract so readers outside the field could understand it.','编辑请科学家换种措辞改写摘要，让专业领域以外的读者也能理解。','The editor asked the scientist to reword the abstract / for readers / outside the field.','reword 指用不同的词再次表达同一意思。','科学家需要调整摘要措辞。'),M('The scientist reworded the abstract by copying every sentence exactly and changing none of its wording.','The scientist reworded the abstract by expressing the same ideas in clearer language.','原样复制且不改措辞并非 reword。','meaning'),[q('Why did the editor ask for a reworded abstract?','to help readers outside the field understand it','to make the abstract longer without changes','to revoke the research permit','编辑希望专业领域外的读者也能理解摘要。',1,'context'),q('What does reword mean?','express the same meaning in different words','change the meaning to its opposite','repeat every word exactly','reword 指用不同措辞表达同一意思。',1,'meaning'),q('Which action rewords a warning?','stating the same warning in simpler terms','copying it letter for letter','removing the warning entirely','用更简单的话表达同一警告属于 reword。',1,'context'),q('What remains the same when a sentence is reworded?','its intended meaning','every original word','its spelling in every language','reword 改变措辞，但保留原意。',1,'meaning')]);
P('rewrite','Rewrite combines re- and write; as a verb it means write something again to improve or shorten it, and as a noun it means the new version.',[C('rewrite.s1','改写；重写','The reporter rewrote the opening paragraph after the editor said the original buried the main finding.','编辑指出原稿把主要发现埋得太深后，记者重写了开头段落。','The reporter rewrote the opening paragraph / after the editor / identified a buried finding.','rewrite.s1 作动词，指为改善或缩短而重新写作。','记者重新组织段落以突出重点。'),C('rewrite.s2','改写稿；修订稿','The director approved the latest rewrite of the script, which gave the supporting character a clearer motive.','导演批准了剧本最新的改写稿，其中配角的动机更加清楚。','The director approved the latest rewrite / which gave a character / a clearer motive.','rewrite.s2 作名词，指重写后形成的新版本。','新稿澄清了角色动机。')],M('The reporter rewrote the opening by submitting the same paragraph unchanged after the editor requested improvements.','The reporter rewrote the opening by changing its structure to highlight the main finding.','原段完全不变就没有重写。','meaning'),[q('Why did the reporter rewrite the opening paragraph?','the main finding was buried in the original','the supporting character needed a motive','the reviewer asked to revoke a permit','记者重写开头，因为原稿没有突出主要发现。',1,'context'),q('What did the latest script rewrite clarify?','the supporting character’s motive','the old opening paragraph’s word count','the revolution’s history','最新改写稿让配角的动机更清楚。',2,'context'),q('In “the reporter rewrote the paragraph,” rewrite is what part of speech?','verb meaning wrote it again','noun meaning the new version','adjective meaning revised already','rewrote 在第一句中是动词，表示重新写。',1,'meaning'),q('In “the latest rewrite,” what does rewrite name?','a new version of the script','the act of revoking a license','a film critic','the latest rewrite 指剧本的新改写稿。',2,'meaning')]);
P('reykjavik','Reykjavik is Iceland’s capital; its name comes from Old Norse reykja (“smoke”) and vík (“bay”), traditionally associated with the area’s steaming hot springs.',C('reykjavik.s1','雷克雅未克','Our flight landed in Reykjavik, Iceland’s capital on the southwest coast, before continuing to a northern village.','我们的航班降落在冰岛西南海岸的首都雷克雅未克，随后继续飞往北部村庄。','Our flight landed in Reykjavik / Iceland’s capital / on the southwest coast.','Reykjavik 是冰岛首都和最大城市，位于西南海岸。','旅客先抵达冰岛首都雷克雅未克。'),M('The travelers landed in Reykjavik, the capital of Iceland, after crossing the Sahara Desert in central Africa.','The travelers landed in Reykjavik, Iceland’s capital on the southwest coast.','冰岛首都雷克雅未克位于冰岛西南海岸，并非非洲撒哈拉沙漠。','meaning'),[q('Where did the flight land before going to the northern village?','Reykjavik','a village on the island’s north coast','a town in central Africa','航班先降落在冰岛首都雷克雅未克。',1,'context'),q('Where is Reykjavik located?','on Iceland’s southwest coast','on the north coast of Africa','in the center of Greenland','Reykjavik 位于冰岛西南海岸。',1,'meaning'),q('What does the name Reykjavik traditionally refer to?','a smoky bay','a circular revolution','a revered harbor master','其古诺尔斯语地名传统上与“冒烟的海湾”有关。',1,'word-formation'),q('Which country has Reykjavik as its capital?','Iceland','Norway','Ireland','Reykjavik 是冰岛的首都。',1,'meaning')]);
P('rhetoric','Rhetoric comes through Latin rhetorica from Greek rhetorike, “the art of oratory”; it can mean persuasive language or impressive-sounding but empty words.',[C('rhetoric.s1','修辞；雄辩术','The mayor used rhetoric about shared responsibility to persuade residents to support the flood barrier.','市长运用强调共同责任的修辞，说服居民支持修建防洪堤。','The mayor used rhetoric / to persuade residents / to support the barrier.','rhetoric.s1 指用语言说服或打动听众的技巧。','市长用有说服力的表达争取支持。'),C('rhetoric.s2','华而不实的言辞','The speech promised clean streets but offered no budget or schedule, so critics dismissed it as empty rhetoric.','演讲承诺改善街道，却没有预算或时间表，因此批评者认为那只是空洞辞令。','Critics dismissed the speech as rhetoric / because it gave promises / without a plan.','rhetoric.s2 指听起来漂亮却不诚恳或无实际内容的话语。','演讲只有承诺而没有行动方案。')],M('The mayor’s rhetoric persuaded nobody because she used no persuasive language and communicated no argument.','The mayor’s rhetoric persuaded residents by presenting a clear argument about shared responsibility.','毫无说服性语言或论证，不符合 rhetoric 的雄辩技巧义。','meaning'),[q('What did the mayor try to persuade residents to support?','the flood barrier','a new rhombus design','the sale of rhinoceros horns','市长运用语言说服居民支持防洪堤。',1,'context'),q('Why did critics call the speech empty rhetoric?','it made promises without a budget or schedule','it offered a detailed and funded plan','it used a regular musical beat','演讲只有承诺而没有预算或时间表，被批评为空洞辞令。',2,'context'),q('What does rhetoric mean in the first sentence?','skillful language used to persuade','a type of volcanic rock','a regular pattern of beats','第一句 rhetoric 指具有说服力的表达技巧。',1,'meaning'),q('Which meaning applies to “empty rhetoric”?','impressive-sounding language with little practical substance','a carefully supported public argument','friendly teasing among classmates','empty rhetoric 指华丽却缺少实际内容的言辞。',2,'meaning')]);
P('rhetorical','Rhetorical is formed from rhetoric and -al; it can describe persuasive language or a question asked to make a point rather than obtain an answer.',[C('rhetorical.s1','修辞的','The speaker’s rhetorical choices—short sentences and repeated contrasts—made the safety argument memorable.','演讲者采用短句和反复对比等修辞手法，使安全论证令人印象深刻。','The speaker’s rhetorical choices / made the safety argument / memorable.','rhetorical.s1 指与说服或打动听众的语言技巧有关。','短句和对比增强了说服效果。'),C('rhetorical.s2','反问的','“Who would ignore a warning like that?” was a rhetorical question; the guide expected no spoken answer.','“谁会忽视那样的警告呢？”是反问句，导览员并不期待有人回答。','“Who would ignore the warning?” / was a rhetorical question / expecting no reply.','rhetorical.s2 描写不以获得答案为目的、用来强调观点的问题。','导览员用反问强调警告的重要性。')],M('The guide asked a rhetorical question and then stopped the tour until a visitor supplied the required factual answer.','The guide asked a rhetorical question to make a point and did not wait for an answer.','若问题要求听众提供事实答案，就不是此处所说的反问。','meaning'),[q('What made the safety argument memorable?','short sentences and repeated contrasts','a river of volcanic rock','a series of tax forms','简短句子和反复对比是演讲者的修辞选择。',1,'context'),q('Did the guide expect an answer to “Who would ignore a warning like that?”','no, it was asked to emphasize a point','yes, the tour could not continue otherwise','only after the visitors reviewed a book','导览员用反问强调观点，并不等待回答。',2,'context'),q('What is a rhetorical question?','a question asked to make a point, not to get an answer','a question that always requires a number','a question about the sound of a rhyme','反问句用于强调观点，而非索取答案。',2,'meaning'),q('Which word does rhetorical come from?','rhetoric','rhythm','rhyolite','rhetorical 由 rhetoric 加 -al 构成。',1,'word-formation')]);
P('rhinoceros','Rhinoceros comes from Greek rhinokeros, “nose-horned,” from rhino (“nose”) and keras (“horn”); it names a large African or Asian animal, or its horn.',[C('rhinoceros.s1','犀牛','A rhinoceros crossed the protected grassland while the ranger watched from a distant vehicle.','一头犀牛穿过受保护的草地，护林员在远处的车里观察。','A rhinoceros crossed the grassland / while the ranger watched / from a distant vehicle.','rhinoceros.s1 指鼻子上方长角的大型非洲或亚洲动物。','护林员远距离观察野生犀牛。'),C('rhinoceros.s2','犀牛角（制品）','The customs officers seized a carved rhinoceros horn at the border and sent it for evidence testing.','海关人员在边境查获一件雕刻的犀牛角制品，并送去取证检测。','Officers seized a carved rhinoceros horn / at the border / for evidence testing.','rhinoceros.s2 可指被交易或加工的犀牛角。','海关查获犀牛角制品。')],M('The ranger identified the rhinoceros by its long feathers and beak as it crossed the grassland.','The ranger identified the rhinoceros by its large body and horn above its nose.','长羽毛和喙是鸟类特征，不是犀牛的识别特征。','meaning'),[q('Where did the ranger see the rhinoceros?','crossing protected grassland','inside the customs evidence room','on a city bus','护林员在受保护的草地上看到犀牛。',1,'context'),q('What did customs officers seize?','a carved rhinoceros horn','a live animal crossing the grassland','a rhombus-shaped ribbon','海关查获了一件雕刻的犀牛角制品。',2,'context'),q('Which feature is associated with a rhinoceros animal?','a horn above its nose','a rotating cylinder','four sides with no angles','犀牛鼻子上方长角。',1,'meaning'),q('What does the Greek element keras mean in rhinoceros?','horn','nose','grassland','rhinoceros 中的希腊语 keras 表示“角”。',1,'word-formation')]);
P('rhombus','Rhombus came through Latin from Greek rhombos, a spinning or turning object; in geometry it is a flat shape with four equal sides but no right angles.',C('rhombus.s1','菱形','The designer arranged four blue tiles into a rhombus, with each side the same length and no corner forming a right angle.','设计师把四块蓝色瓷砖排成菱形，每条边等长且没有直角。','The designer arranged the tiles into a rhombus / with equal sides / and no right angles.','rhombus 指四边相等、但角不为直角的平面图形。','图形四边等长但不含直角。'),M('The designer called the square a rhombus with unequal sides and only three corners.','The designer called the four-sided equal-edged shape a rhombus.','只有三角或边不相等的图形不符合此处菱形的定义。','meaning'),[q('What was true of the rhombus’s sides?','all four had the same length','two sides were missing','each side was a different length','瓷砖排成的菱形四边等长。',1,'context'),q('Did the rhombus have right angles?','no','yes, at every corner','it had no corners','题中的菱形没有直角。',1,'context'),q('What is a rhombus?','a four-sided flat shape with equal sides','a four-sided shape with unequal sides only','a round shape used to hold bullets','rhombus 是四边相等的平面图形。',1,'meaning'),q('Which feature distinguishes the described rhombus from a square?','its corners are not right angles','it has four equal sides','it is flat','题中菱形的角不是直角，因此不同于正方形。',1,'meaning')]);
P('rhyme','Rhyme came through Old French rime; its deeper origin is uncertain. As a noun it means matching end sounds or their use, and as a verb it means end with the same sound.',[C('rhyme.s1','押韵；韵脚','The children noticed the rhyme between “light” and “night” and repeated the couplet aloud.','孩子们注意到 light 和 night 押韵，便大声重复这两行诗。','The children noticed the rhyme / between “light” and “night” / and repeated the couplet.','rhyme.s1 作名词，指词尾相同的声音或押韵现象。','两个词的尾音相同。'),C('rhyme.s2','（与……）押韵','The word “stone” rhymes with “phone,” but it does not rhyme with “sun.”','stone 与 phone 押韵，但不与 sun 押韵。','“Stone” rhymes with “phone” / but not / with “sun.”','rhyme.s2 作动词，指以相同声音结尾。','stone 和 phone 的尾音相同。')],M('The children said “light” and “night” rhyme even though the two words end with completely different sounds.','The children said “light” and “night” rhyme because the words share the same ending sound.','若词尾发音完全不同，就不构成押韵。','meaning'),[q('Which words did the children notice rhyming?','light and night','stone and sun','light and stone','孩子们发现 light 和 night 的尾音相同。',1,'context'),q('Which word rhymes with “stone”?','phone','sun','night','stone 与 phone 押韵。',2,'context'),q('What can rhyme name as a noun?','matching end sounds or their use','a four-sided geometric shape','a volcanic rock','名词 rhyme 可指相同的词尾音或押韵现象。',1,'meaning'),q('What does rhyme mean as a verb?','end with the same sound','have four equal sides','move in a regular circle','动词 rhyme 指以相同声音结尾。',2,'meaning')]);
P('rhyolite','Rhyolite was coined from Greek rhyax (“stream of lava”) and lithos (“stone”); it is a pale, silica-rich volcanic rock compositionally equivalent to granite.',C('rhyolite.s1','流纹岩','The geologist identified pale rhyolite in the cliff, noting its fine crystals and light-colored bands.','地质学家在峭壁上辨认出浅色流纹岩，并注意到其中的细小晶体和浅色条带。','The geologist identified rhyolite / by its pale bands / and fine crystals.','rhyolite 指富含二氧化硅、常呈浅色带状的火山岩。','峭壁上的岩石有流纹岩的浅色条带。'),M('The geologist identified the pale, silica-rich rhyolite as a soft plant leaf with no volcanic origin.','The geologist identified the pale, silica-rich rock as rhyolite, a volcanic rock.','流纹岩是火山岩，不是植物叶片。','meaning'),[q('What color bands helped identify the rhyolite?','pale bands','bright red stripes','no visible bands','地质学家注意到流纹岩的浅色条带。',1,'context'),q('What kind of rock is rhyolite?','a silica-rich volcanic rock','a sediment made only of plant leaves','a metal alloy','rhyolite 是富含二氧化硅的火山岩。',1,'meaning'),q('Which rock sample is most likely rhyolite?','a light-colored, fine-crystal volcanic rock','a living plant with soft green leaves','a piece of polished ribbon','浅色、晶体细小的火山岩可能是 rhyolite。',1,'context'),q('What does the Greek element lithos mean?','stone','stream','beat','rhyolite 词名中的 lithos 表示“石头”。',1,'word-formation')]);
P('rhythm','Rhythm comes from Greek rhythmos, “measured motion”; it means a regular pattern of beats in music or speech, or a regular pattern in how something happens.',[C('rhythm.s1','节奏；韵律','The drummer kept a steady rhythm while the choir sang the final verse.','合唱团唱最后一段时，鼓手保持着稳定的节奏。','The drummer kept a steady rhythm / while the choir / sang the final verse.','rhythm.s1 指音乐、言语或诗歌中规律的节拍模式。','鼓手为合唱提供稳定节拍。'),C('rhythm.s2','规律；生活节奏','The clinic gradually returned to its normal rhythm after the winter vaccination campaign ended.','冬季疫苗接种活动结束后，诊所逐渐恢复了正常运转节奏。','The clinic returned to its normal rhythm / after the vaccination campaign / ended.','rhythm.s2 指事情发生或生活运转的规律模式。','诊所恢复日常工作规律。')],M('The drummer kept a steady rhythm by changing beats at random so that no pattern could be heard.','The drummer kept a steady rhythm by repeating an even pattern of beats.','随机改变节拍、没有规律，不是稳定节奏。','meaning'),[q('What did the drummer maintain for the choir?','a steady pattern of beats','a new volcanic rock sample','a ribbon for the award','鼓手为合唱团保持稳定节奏。',1,'context'),q('When did the clinic return to its normal rhythm?','after the vaccination campaign ended','while it was just beginning the campaign','after a rhombus was drawn','疫苗活动结束后诊所恢复正常工作节奏。',2,'context'),q('What does rhythm mean in the music example?','a regular pattern of beats','a regular pattern in business routines','a type of language persuasion','音乐中的 rhythm 指规律的节拍。',1,'meaning'),q('What does “the rhythm of daily life” refer to?','the regular pattern of everyday activities','a musical instrument only','a public review','daily life 的 rhythm 指日常活动的规律。',2,'meaning')]);
P('rhythm and blues','Rhythm and blues is a compound name for a popular music style developed from blues and gospel, marked by a strong rhythm.',C('rhythm and blues.s1','节奏布鲁斯（R&B）','The radio station devoted Friday evening to rhythm and blues, playing recordings with strong beats and blues-influenced vocals.','电台周五晚间专门播放节奏布鲁斯，选曲节拍鲜明，演唱受布鲁斯影响。','The station devoted Friday evening to rhythm and blues / with strong beats / and blues-influenced vocals.','rhythm and blues 指一种节奏鲜明、源于布鲁斯和福音音乐的流行音乐风格。','节目播放具有布鲁斯风格的强节拍音乐。'),M('The station called its program rhythm and blues even though it played only silent orchestral music with no beat or blues influence.','The station played rhythm and blues recordings with strong beats and blues-influenced vocals.','没有节拍且无布鲁斯影响的无声音乐不符合R&B风格。','meaning'),[q('When did the radio station feature rhythm and blues?','Friday evening','Monday morning','during the city council meeting','电台周五晚间播放节奏布鲁斯。',1,'context'),q('What musical features did the program include?','strong beats and blues-influenced vocals','silent orchestral passages','spoken tax reports','节目选曲节拍鲜明，演唱受布鲁斯影响。',1,'context'),q('What is rhythm and blues?','a popular music style developed from blues and gospel','a type of pale volcanic rock','a formal review of a song','rhythm and blues 是源自布鲁斯和福音音乐的流行风格。',1,'meaning'),q('What is the common abbreviation for rhythm and blues?','R&B','R&R','B&B','rhythm and blues 常缩写为 R&B。',1,'meaning')]);
P('rhythmic','Rhythmic is formed from rhythm and -ic; it describes sounds or movements that repeat in a regular pattern, or words arranged in a pleasing beat.',[C('rhythmic.s1','有节奏的','The rhythmic tapping of the train wheels grew softer as the carriage moved farther from the station.','列车车厢离车站越来越远时，车轮有节奏的敲击声渐渐变轻。','The rhythmic tapping grew softer / as the carriage / moved away from the station.','rhythmic.s1 指声音或动作按规律重复。','车轮发出规律的敲击声。'),C('rhythmic.s2','有韵律的','The poet’s rhythmic lines made the children remember the safety instructions after one reading.','诗人富有韵律的诗句让孩子们读一遍就记住了安全指示。','The poet’s rhythmic lines / helped the children remember / the instructions.','rhythmic.s2 描写词语按悦耳节拍排列。','有韵律的诗句便于记忆。')],M('The train made rhythmic tapping by striking the rails at completely irregular intervals with no repeated pattern.','The train made rhythmic tapping by producing a regular repeated pattern of beats.','完全不规律且无重复模式的敲击不属于 rhythmic。','meaning'),[q('What made the rhythmic sound?','the train wheels tapping','the radio station’s tax report','the geologist’s rock sample','列车车轮发出有规律的敲击声。',1,'context'),q('Why did children remember the instructions?','the poet arranged them in rhythmic lines','the train repeated them irregularly','the children revoked the rules','诗人把指示写成有韵律的诗句，便于记忆。',2,'context'),q('What does rhythmic mean in the train example?','repeating in a regular pattern','loud but irregular','related to a geometric shape','列车例句中 rhythmic 指声音规律重复。',1,'meaning'),q('What does rhythmic mean in “rhythmic lines”?','words arranged in a pleasing regular beat','words that all have the same meaning','words written on a ribbon','rhythmic lines 指具有悦耳规律节拍的诗句。',2,'meaning')]);
P('rhythmical','Rhythmical is formed from rhythm and -ical; it describes something marked by a steady beat or regular pattern.',C('rhythmical.s1','有节奏的；有韵律的','The rhythmical motion of the loom helped the weaver keep each row of cloth even.','织机有节奏的运动帮助织工把每一行布织得均匀。','The rhythmical motion of the loom / helped the weaver / keep each row even.','rhythmical 描写稳定节拍或规律模式。','织机以规律运动帮助织布。'),M('The loom’s motion was rhythmical because it started and stopped at unpredictable intervals with no steady beat.','The loom’s motion was rhythmical because it repeated at a steady, regular pace.','没有稳定节拍且时间不可预测的运动不符合 rhythmical。','meaning'),[q('What did the loom’s rhythmical motion help the weaver do?','keep each row of cloth even','write a review of the loom','revoke the factory’s license','织机的规律运动帮助织工把布织得均匀。',1,'context'),q('What does rhythmical describe?','a steady beat or regular pattern','a complete absence of pattern','a sudden feeling of disgust','rhythmical 指稳定节拍或规律模式。',1,'meaning'),q('Which machine operates rhythmically?','a loom that repeats the same movement at a steady pace','a machine that changes speed randomly every second','a device that never moves','匀速重复相同动作的织机具有 rhythmical 运动。',1,'context'),q('Which related word is rhythmical based on?','rhythm','reverence','rhyolite','rhythmical 由 rhythm 加 -ical 构成。',1,'word-formation')]);
P('rhythmically','Rhythmically is formed from rhythmical and -ly; it means with a repeated, regular movement or sound.',C('rhythmically.s1','有节奏地','The dancers stepped rhythmically to the drum, landing together on every fourth beat.','舞者随着鼓点有节奏地迈步，每逢第四拍同时落脚。','The dancers stepped rhythmically / to the drum / landing on every fourth beat.','rhythmically 修饰动作，表示动作按规律节拍重复。','舞者跟着鼓点整齐迈步。'),M('The dancers moved rhythmically by changing every step at a random time and never following the drumbeat.','The dancers moved rhythmically by repeating steps in time with the drumbeat.','完全随机且不跟节拍的动作不属于 rhythmically。','meaning'),[q('What did the dancers follow?','the drumbeat','the reviewer’s notes','a rhombus outline','舞者随着鼓点有节奏地迈步。',1,'context'),q('On which beat did they land together?','every fourth beat','every seventh minute','only after the music stopped','舞者每逢第四拍同时落脚。',1,'context'),q('What does rhythmically mean?','with a repeated regular movement or sound','without any repeated timing','in a deeply respectful manner','rhythmically 指动作或声音有规律地重复。',1,'meaning'),q('Which adjective is the base of rhythmically?','rhythmical','reverent','reversible','rhythmically 由 rhythmical 加 -ly 构成。',1,'word-formation')]);
P('rib','Rib is an old Germanic word, related to Old Norse rif; it can mean a curved chest bone, a supporting ridge, or friendly teasing.',[C('rib.s1','肋骨','The doctor ordered an X-ray after the cyclist complained of pain around one rib.','骑行者抱怨一根肋骨附近疼痛后，医生安排了X光检查。','The doctor ordered an X-ray / after pain around one rib / was reported.','rib.s1 指构成胸廓、保护胸腔器官的弯曲骨头。','医生检查受伤的肋骨。'),C('rib.s2','肋状支撑物；伞骨','A metal rib inside the umbrella kept the fabric from collapsing in the wind.','雨伞内部的金属伞骨使伞布在风中不至于塌下。','A metal rib inside the umbrella / kept the fabric / from collapsing.','rib.s2 可指支撑或加固物体的弯曲条状构件。','金属伞骨支撑伞布。'),C('rib.s3','开玩笑地取笑','Her teammates ribbed her about the bright ribbon on her helmet, but she wore it proudly.','队友拿她头盔上的亮色丝带开玩笑，但她仍自豪地戴着它。','Her teammates ribbed her / about the bright ribbon / on her helmet.','rib.s3 作动词，指友好地取笑某人。','队友友善地打趣她的丝带。')],M('The doctor said the cyclist had a rib in her chest but explained that ribs are soft fabric decorations, not bones.','The doctor said the cyclist had injured a rib, one of the curved bones in the chest.','rib 的身体义是胸部的骨头，不是布制装饰。','meaning'),[q('Why did the cyclist receive an X-ray?','pain near one chest bone','a bright ribbon on her helmet','a broken umbrella rib','骑行者因肋骨附近疼痛而接受X光检查。',1,'context'),q('What did the umbrella’s metal rib do?','supported the fabric in the wind','decorated a helmet','protected the chest','金属伞骨支撑伞布，防止被风吹塌。',2,'context'),q('How did teammates rib her?','they teased her in a friendly way about her ribbon','they injured one of her chest bones','they removed the umbrella support','队友拿她头盔上的丝带开玩笑，属于友好打趣。',3,'context'),q('Which use of rib means “tease”?','Her friends ribbed her about the colorful hat.','She fractured a rib in the fall.','A rib supported the umbrella.','第一句中的 ribbed 表示友好地取笑。',1,'meaning')]);
P('ribbon','Ribbon came through French ruban; its deeper origin is uncertain. It means a long narrow strip of cloth for tying or decoration, or a band worn as a prize or any long narrow strip.',[C('ribbon.s1','丝带；缎带','She tied a red ribbon around the jar of homemade jam before giving it to her neighbor.','她在自制果酱罐上系了一条红丝带，然后送给邻居。','She tied a red ribbon / around the jam jar / before giving it away.','ribbon.s1 指用于系扎或装饰的长而窄的布条。','红丝带装饰果酱罐。','ribbon 通常指窄长条带。'),C('ribbon.s2','勋带；带状物','The swimmer wore a blue ribbon from the regional championship on her jacket.','游泳运动员夹克上佩戴着一条地区锦标赛的蓝色奖带。','The swimmer wore a blue ribbon / from the championship / on her jacket.','ribbon.s2 可指奖项勋带或其他细长带状物。','蓝色奖带代表比赛荣誉。')],M('She decorated the jam jar with a ribbon by wrapping it in a wide metal plate instead of a narrow strip.','She decorated the jam jar with a ribbon by tying a narrow strip of cloth around it.','宽金属板不是用于装饰的窄布条。','meaning'),[q('What did she tie around the jam jar?','a red strip of cloth','a metal umbrella rib','a rice stalk','她用红丝带装饰果酱罐。',1,'context'),q('Where did the swimmer wear the blue ribbon?','on her jacket','around a jar of jam','inside a rhombus','游泳运动员把蓝色奖带佩戴在夹克上。',1,'context'),q('What is a ribbon in the first example?','a long narrow strip of cloth','a curved bone in the chest','a style of music','第一句中的 ribbon 是用于装饰的细长布条。',1,'meaning'),q('Which meaning applies to the championship ribbon?','a band worn as a prize','a strip used to close a jar only','a piece of volcanic rock','比赛奖带属于表示荣誉的 ribbon。',2,'meaning')]);
P('rice','Rice comes through Old French ris and ultimately from Greek oryza; it can mean the grain itself or the cooked grain served as food.',[C('rice.s1','大米；稻米','The farmer planted rice in shallow flooded plots and harvested the mature grain in autumn.','农民在浅水田里种植水稻，并于秋季收割成熟稻谷。','The farmer planted rice / in flooded plots / and harvested the grain in autumn.','rice.s1 指作为食物种植的稻谷或米粒。','农民收获田中成熟的稻米。'),C('rice.s2','米饭','We served rice with the vegetable stew, adding a little water so the grains stayed soft.','我们把米饭配蔬菜炖菜食用，并加少量水让米粒保持松软。','We served rice / with the vegetable stew / and kept the grains soft.','rice.s2 指煮熟后作为餐食的大米。','熟米饭与炖菜一起上桌。')],M('The farmer planted rice in the flooded field but harvested ripe fish from the water.','The farmer planted rice in the flooded field and harvested the mature grain.','稻田里收获的是成熟稻谷，不是鱼。','meaning'),[q('Where did the farmer plant rice?','in shallow flooded plots','in a dry museum hall','on a ribbon','农民在浅水田里种植水稻。',1,'context'),q('What did the family serve with vegetable stew?','cooked rice','raw rice plants','a strip of cloth','家人将米饭与蔬菜炖菜一起食用。',1,'context'),q('What does rice mean in the farming sentence?','the grain crop grown in fields','the cooked meal only','a narrow cloth strip','种植和收割语境中的 rice 指稻米作物。',1,'meaning'),q('What does rice mean in “served rice with stew”?','cooked grain eaten as food','a plant growing in a field','a regular beat in music','与炖菜同食的 rice 指煮熟的米饭。',2,'meaning')]);
P('rice field','Rice field combines rice and field; it names land used to grow rice, often kept flooded during cultivation.',C('rice field.s1','稻田','A heron stood at the edge of the rice field while farmers transplanted young seedlings into the water.','农民把幼苗移栽进水田时，一只苍鹭站在稻田边。','A heron stood beside the rice field / while farmers transplanted seedlings / into the water.','rice field 指种植水稻的田地，常以浅水灌溉。','农民在水田里移栽稻苗。'),M('The rice field was the dry parking lot where farmers stored cars and grew no rice plants.','The rice field was the flooded plot where farmers transplanted rice seedlings.','不种水稻的停车场不能称为 rice field。','meaning'),[q('What were farmers transplanting?','young rice seedlings','rhinoceros horns','red ribbons','农民把幼小的稻苗移栽进田里。',1,'context'),q('Where did the heron stand?','at the edge of the rice field','inside a city hall','on a music stage','苍鹭站在稻田边。',1,'context'),q('What is a rice field?','land used to grow rice','a field covered with ribbons','a place where rice is served after cooking','rice field 是种植水稻的田地。',1,'meaning'),q('Why may a rice field be kept flooded?','rice seedlings are often grown in shallow water','the field is used as a swimming pool','to grow volcanic rocks','稻田常以浅水灌溉来种植水稻。',1,'meaning')]);
P('rich','Rich comes from Old English rīċe, “powerful or wealthy”; it can mean having much money, containing a lot of something valuable, or heavy/deep in flavor, color, or sound.',[C('rich.s1','富有的；有钱的','The rich investor donated part of her fortune to fund free clinics in rural villages.','这位富有的投资者捐出部分财产，为乡村免费诊所提供资金。','The rich investor donated / part of her fortune / to rural clinics.','rich.s1 指拥有大量金钱或贵重财产。','投资者拥有财富并进行捐赠。'),C('rich.s2','丰富的；富于','The soil is rich in minerals, which helps the orchard produce healthy fruit without extra fertilizer.','土壤富含矿物质，因此果园无需额外肥料也能结出健康果实。','The soil is rich in minerals / which helps the orchard / grow healthy fruit.','rich.s2 指含有大量有用或有趣的成分。','矿物质丰富的土壤有利于果树生长。'),C('rich.s3','油腻的；浓郁的；深厚的','The rich chocolate cake was so buttery that a small slice was enough for each guest.','这块巧克力蛋糕奶油味浓郁，每位客人吃一小块就够了。','The rich chocolate cake was buttery / so a small slice / satisfied each guest.','rich.s3 可指食物浓郁油腻，也可形容深沉的颜色或声音。','蛋糕味道浓厚，少量即可。')],M('The rich investor owned no money or possessions and could not afford a meal.','The rich investor owned substantial wealth and donated part of her fortune.','一无所有、无法负担用餐的人不符合“富有”的含义。','meaning'),[q('What did the rich investor donate?','part of her fortune','the orchard’s mineral soil','a slice of chocolate cake','这位富有的投资者捐出部分财富。',1,'context'),q('Why is the orchard soil rich?','it contains many minerals','it is made entirely of chocolate','it has no useful nutrients','土壤富含矿物质，因此果树长势良好。',2,'context'),q('What does rich describe in “a rich chocolate cake”?','a buttery, intense flavor','a large amount of money','a field full of rice','这里 rich 描写蛋糕油腻浓郁的味道。',3,'context'),q('Which use of rich means “containing a great deal”?','soil rich in minerals','a rich investor','a rich chocolate flavor','rich in minerals 指含有大量矿物质。',2,'meaning')]);
P('riches','Riches comes from rich with the plural-forming ending; it means a large amount of money and valuable property.',C('riches.s1','巨额财富','The explorer returned from the island with riches in the form of rare coins, paintings, and jewels.','探险家带着珍贵钱币、画作和珠宝等财富从岛上归来。','The explorer returned with riches / including rare coins / paintings, and jewels.','riches 指大量金钱和有价值的财物。','探险家带回多种珍贵财物。'),M('The explorer returned with riches consisting of broken twigs and worthless scraps with no monetary or property value.','The explorer returned with riches consisting of valuable coins, paintings, and jewels.','毫无价值的碎枝不能构成巨额财富。','meaning'),[q('What forms did the explorer’s riches take?','coins, paintings, and jewels','broken twigs and scraps','rice and ribbons','探险家带回珍贵钱币、画作和珠宝。',1,'context'),q('What does riches mean?','a large amount of money and valuable property','a rich flavor in a small dessert','a regular beat in music','riches 指巨额金钱和有价值的财产。',1,'meaning'),q('Which person has riches?','someone who owns valuable property and substantial wealth','someone carrying one empty box','someone studying a single exam note','拥有大量财富和贵重财物的人拥有 riches。',1,'context'),q('Which word is riches formed from?','rich','rhyme','rib','riches 来自 rich，加复数形式构成名词。',1,'word-formation')]);
P('richly','Richly is formed from rich and -ly; it means with abundant color or decoration, or fully and deservedly.',[C('richly.s1','华丽地；丰富地','The hall was richly decorated with embroidered banners, carved panels, and gold-colored lamps.','大厅装饰得十分华丽，挂着刺绣横幅、雕刻木板和金色灯具。','The hall was richly decorated / with banners / panels, and lamps.','richly.s1 指装饰、颜色或品质丰富华丽。','大厅布置有多种精美装饰。'),C('richly.s2','完全地；理所当然地','After years of patient coaching, the teacher was richly rewarded when her students won the regional competition.','多年耐心指导后，学生赢得地区比赛，这位老师得到了丰厚回报。','The teacher was richly rewarded / after years of coaching / and the students’ win.','richly.s2 可表示充分地、完全值得地。','老师的多年付出获得了丰厚回报。')],M('The hall was richly decorated with bare walls, no furnishings, and no color or ornament.','The hall was richly decorated with detailed banners, carved panels, and lamps.','空荡、无色且无装饰的房间不是 richly decorated。','meaning'),[q('What decorated the hall richly?','embroidered banners, carved panels, and lamps','bare walls with no ornament','one rice stalk','大厅里有刺绣横幅、雕刻木板和灯具。',1,'context'),q('What happened to the teacher after her students won?','she was richly rewarded','she was revoked from her job','she was rid of the students','学生获胜后，老师得到了丰厚回报。',2,'context'),q('What does richly mean in “richly decorated”?','with abundant ornament or detail','only partly and sparsely','with a regular beat','richly decorated 指装饰丰富华丽。',1,'meaning'),q('What does richly mean in “richly rewarded”?','fully and deservedly','decorated with many colors','in a rhythmical way','richly rewarded 表示得到充分且应得的回报。',2,'meaning')]);
P('richness','Richness is formed from rich and -ness; it means the state of containing much of something desirable or having a full flavor, color, or sound.',C('richness.s1','丰富；浓郁','The richness of the soup came from roasted vegetables and a slow-cooked stock rather than added cream.','这道汤的浓郁味道来自烤蔬菜和慢炖高汤，而不是额外添加的奶油。','The richness of the soup came / from roasted vegetables / and slow-cooked stock.','richness 指某物含有大量理想成分或味道、色彩、声音饱满。','汤的浓郁来自食材和高汤。'),M('The soup had richness because it was watery, flavorless, and contained none of the ingredients that gave it depth.','The soup had richness because its roasted vegetables and stock gave it a full flavor.','寡淡无味的汤不具备浓郁风味。','meaning'),[q('What created the soup’s richness?','roasted vegetables and slow-cooked stock','added water only','a red ribbon around the bowl','烤蔬菜和慢炖高汤带来了汤的浓郁味道。',1,'context'),q('What does richness mean here?','a full and deep flavor','a large amount of property','a question used to make a point','这里 richness 指饱满浓郁的味道。',1,'meaning'),q('Which painting shows richness of color?','a canvas with deep, varied hues','a blank canvas with no pigment','a page containing only numbers','色彩深沉多样的画作具有 richness of color。',1,'context'),q('Which suffix forms the noun richness?','-ness','-er','-ize','rich 加 -ness 形成名词 richness。',1,'word-formation')]);
P('rid','Rid is recorded in Middle English with senses of freeing or clearing; its deeper origin is uncertain. It means remove something unwanted or free someone from it, commonly in get rid of.',[C('rid.s1','使摆脱；清除','The cleanup crew worked through the night to rid the beach of plastic bottles before the nesting season.','清理队连夜清除海滩上的塑料瓶，以赶在鸟类筑巢季前完成。','The crew worked overnight / to rid the beach / of plastic bottles.','rid.s1 指从某人或某地清除不需要的东西。','清理队清除海滩垃圾。'),C('rid.s2','摆脱；不再受……影响','After changing her phone settings, Lena got rid of the constant notification sounds.','调整手机设置后，莉娜摆脱了不断响起的通知声。','Lena got rid of the notification sounds / after changing / her phone settings.','rid.s2 常用于 get rid of，表示丢弃某物或不再受其影响。','莉娜关闭通知音，摆脱持续打扰。')],M('The cleanup crew rid the beach of plastic bottles by adding more bottles to the sand and leaving them there.','The cleanup crew rid the beach of plastic bottles by collecting and removing them.','把更多瓶子留在海滩上与清除垃圾的意思相反。','meaning'),[q('What did the cleanup crew remove from the beach?','plastic bottles','nesting birds','rice plants','清理队从海滩清除了塑料瓶。',1,'context'),q('How did Lena get rid of constant notification sounds?','she changed her phone settings','she added more alerts','she wrote a review of the phone','莉娜调整手机设置后摆脱了持续通知音。',2,'context'),q('What does rid mean in “rid the beach of bottles”?','remove unwanted things from a place','decorate a place richly','make a place revolve','这里 rid 指从海滩清除不需要的东西。',1,'meaning'),q('Which phrase commonly uses rid to mean stop being affected?','get rid of','revolve around','in retrospect','get rid of 表示摆脱或丢弃某物。',2,'meaning')]);
})();
